const project={name:"Faerie Glen Residential",location:"Pretoria, Gauteng",stage:"Design",progress:46,client:"Evergreen Property Holdings",professional:"Justin Kruger · PrArch",municipality:"City of Tshwane",revision:"P03"};
const tones={core:"var(--teal)",teal:"var(--teal)",cobalt:"var(--cobalt)",lavender:"var(--lavender)",coral:"var(--coral)",amber:"var(--amber)"};
const globalItems=[
 {id:"command",label:"OS Command Centre",icon:"dashboard",tone:"core",meta:"Home"},
 {id:"projects",label:"Project Space",icon:"projects",tone:"core",meta:"Datum"},
 {id:"tools",label:"Workspace Tools",icon:"tools",tone:"lavender",meta:String(Object.keys(TOOLS).length)},
 {id:"inbox",label:"Inbox & Collaboration",icon:"inbox",tone:"coral",meta:"7"},
 {id:"documents",label:"Documents",icon:"document",tone:"core",meta:"128"},
 {id:"finance",label:"Finance & Payments",icon:"finance",tone:"amber",meta:"4"},
 {id:"knowledge",label:"Knowledge & CPD",icon:"knowledge",tone:"cobalt",meta:""},
 {id:"feedback",label:"Feedback Intelligence",icon:"feedback",tone:"lavender",meta:"Loop"},
 {id:"settings",label:"Settings",icon:"settings",tone:"core",meta:""}
];
let state={global:"projects",mode:"project",tool:null,toolTab:0,inspector:"context",rail:false,frameReady:false};
const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];

const iconShapes={
 dashboard:'<rect class="outline" x="3" y="3" width="7" height="7" rx="2"/><rect class="outline" x="14" y="3" width="7" height="7" rx="2"/><rect class="outline" x="3" y="14" width="7" height="7" rx="2"/><rect class="outline" x="14" y="14" width="7" height="7" rx="2"/><path class="fold" d="M14 14h7v7z"/>',
 projects:'<path class="outline" d="M3 7.5h7l2-2h9v13.5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><path class="line" d="M3 9h18"/><path class="fold" d="M15 21h6v-6z"/>',
 tools:'<rect class="outline" x="3" y="3" width="18" height="18" rx="4"/><path class="line" d="M8 8h8M8 12h5M8 16h8"/><path class="fold" d="M16 21h5v-5z"/>',
 inbox:'<path class="outline" d="M4 5h16a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H8l-4 3v-15a2 2 0 0 1 2-2z"/><path class="line" d="M8 10h8M8 14h5"/><path class="fold" d="M17 19h3l-3 3z"/>',
 document:'<path class="outline" d="M6 2h9l5 5v15H6a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2z"/><path class="line" d="M8 12h8M8 16h6"/><path class="fold" d="M15 2v5h5z"/>',
 finance:'<rect class="outline" x="3" y="6" width="18" height="14" rx="3"/><path class="line" d="M3 10h18M16 15h2"/><path class="fold" d="M16 20h5v-5z"/>',
 knowledge:'<path class="outline" d="M4 4h7a3 3 0 0 1 3 3v13a3 3 0 0 0-3-3H4z"/><path class="outline" d="M20 4h-7a3 3 0 0 0-3 3v13a3 3 0 0 1 3-3h7z"/><path class="fold" d="M16 17h4v-4z"/>',
 settings:'<circle class="outline" cx="12" cy="12" r="4"/><path class="line" d="M12 2v3M12 19v3M2 12h3M19 12h3M4.9 4.9 7 7M17 17l2.1 2.1M19.1 4.9 17 7M7 17l-2.1 2.1"/><path class="fold" d="M16 16l4 1-3 3z"/>',
 wingman:'<path class="outline" d="M3 5l9 6 8-5-5 13-4-5-5 2z"/><path class="line" d="M12 11l3 8"/><path class="fold" d="M12 11l8-5-5 7z"/>',
 planning:'<path class="outline" d="M5 3h14a2 2 0 0 1 2 2v14H3V5a2 2 0 0 1 2-2z"/><path class="line" d="M7 7h10M7 11h6M8 19v3M16 19v3"/><path class="fold" d="M15 19h6v-6z"/>',
 municipal:'<path class="outline" d="M3 9h18M5 9v10M9 9v10M15 9v10M19 9v10M3 19h18M12 3l9 5H3z"/><path class="fold" d="M16 19h5v-5z"/>',
 xa:'<path class="outline" d="M12 2l8 4v6c0 5-3.4 8.5-8 10-4.6-1.5-8-5-8-10V6z"/><path class="line" d="M13 6l-4 7h4l-2 5 5-8h-4z"/><path class="fold" d="M16 16l4-4v5z"/>',
