function icon(name,size=24){let shape=iconShapes[name]||iconShapes.document;return `<svg class="ax-icon" width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true">${shape}</svg>`}
function toneStyle(t){return `--tone:${tones[t]||"var(--teal)"}`}

function renderGlobalMenu(){
 q("#globalMenu").innerHTML=globalItems.map(i=>`<button class="os-item ${state.global===i.id?"active":""}" style="${toneStyle(i.tone)}" onclick="openGlobal('${i.id}')" aria-label="${i.label}"><span class="icon-wrap">${icon(i.icon,24)}</span><span class="os-label">${i.label}</span><span class="os-meta">${i.meta}</span></button>`).join("");
}
function toggleRail(){state.rail=!state.rail;q("#app").classList.toggle("rail-expanded",state.rail)}
function toggleNavigator(){q("#app").classList.toggle("nav-closed")}
function toggleInspector(){q("#app").classList.toggle("inspector-closed")}
function setInspector(tab,el){state.inspector=tab;qa(".inspect-tab").forEach(x=>x.classList.remove("active"));el.classList.add("active");renderInspector()}
function setMode(mode){state.mode=mode;state.global=mode==="project"?"projects":"tools";state.tool=null;state.toolTab=0;renderAll()}
function openGlobal(id){state.global=id;if(id==="projects"){state.mode="project";state.tool=null}else if(id==="tools"){state.mode="standalone";state.tool=null}else if(id==="command"){state.mode="project";state.tool="command";state.toolTab=0}else{state.tool=null}renderAll()}
function openProjectSpace(){state.mode="project";state.global="projects";state.tool=null;state.toolTab=0;renderAll()}
function openStandalone(){state.mode="standalone";state.global="tools";state.tool=null;state.toolTab=0;renderAll()}
function openTool(id,mode=state.mode){state.tool=id;state.mode=mode;state.global=mode==="project"?"projects":"tools";state.toolTab=0;state.frameReady=false;renderAll()}
function attachProject(){state.mode="project";state.global="projects";renderAll();setTimeout(()=>loadToolFrame(state.tool),30)}
function setToolTab(index){state.toolTab=index;renderNavigator();invokeToolAction(TOOLS[state.tool].tabs[index]);renderInspector()}
function renderAll(){renderGlobalMenu();renderNavigator();renderMain();renderInspector();renderTopbar()}
function renderTopbar(){
 q("#navToggle").innerHTML=icon("menu",19);q("#wingmanTop").innerHTML=icon("wingman",19);q("#inspectToggle").innerHTML=icon("inspector",19);
 q("#scopePill").textContent=state.mode==="project"?"Project orientation":"Standalone orientation";
 q("#projectChip").textContent=state.mode==="project"?"● "+project.name:"○ Portfolio / unassigned";
 let crumb="Architex OS › ";
 if(state.tool) crumb+=(state.mode==="project"?`Projects › ${project.name} › `:"Standalone Tools › ")+`<b>${TOOLS[state.tool].name}</b>`;
 else if(state.global==="projects")crumb+=`Projects › <b>${project.name}</b>`;
 else crumb+=`<b>${globalItems.find(x=>x.id===state.global)?.label||"Workspace"}</b>`;
 q("#breadcrumb").innerHTML=crumb;
}
function modeSwitch(){return `<div class="mode-switch"><button class="${state.mode==="project"?"active":""}" onclick="setMode('project')">Project</button><button class="${state.mode==="standalone"?"active":""}" onclick="setMode('standalone')">Standalone</button></div>`}
function renderNavigator(){
 const nav=q("#navigator");
 if(state.tool){
  const t=TOOLS[state.tool];
  nav.innerHTML=`<div class="nav-head"><div class="kicker">${state.mode==="project"?"Project tool":"Standalone tool"}</div><div class="nav-title">${t.name}</div><div class="nav-sub">${state.mode==="project"?project.name+" · "+project.stage+" stage":"Portfolio-wide workspace · project optional"}</div>${modeSwitch()}${state.mode==="project"?`<select class="project-select" name="projectSelector" aria-label="Active project"><option>${project.name}</option><option>Camps Bay Residence</option><option>12 Riverside Ave</option></select>`:""}</div>
  <div class="back-row" onclick="${state.mode==="project"?"openProjectSpace()":"openStandalone()"}">${icon("projects",16)} ${state.mode==="project"?"Back to datum project space":"Back to standalone library"}</div>
  <div class="nav-section"><div class="nav-heading">Inside ${t.name}</div>${t.tabs.map((x,i)=>`<button class="nav-row ${state.toolTab===i?"active":""}" style="${toneStyle(t.tone)}" onclick="setToolTab(${i})"><span class="nav-icon">${icon(i===0?t.icon:"document",19)}</span><span>${x.label}</span>${x.badge?`<span class="badge">${x.badge}</span>`:""}</button>`).join("")}</div>
  <div class="nav-note"><b>Original functionality preserved.</b><br>This navigation drives the supplied module sample inside the central workspace. The original module shell is hidden so it inherits the Datum OS navigation instead.</div>`;
  return;
 }
 if(state.mode==="project"){
  nav.innerHTML=`<div class="nav-head"><div class="kicker">Active project</div><div class="nav-title">${project.name}</div><div class="nav-sub">${project.location} · ${project.stage} stage · Rev ${project.revision}</div>${modeSwitch()}<select class="project-select" name="projectSelector" aria-label="Active project"><option>${project.name}</option><option>Camps Bay Residence</option><option>12 Riverside Ave</option></select></div>
  <div class="nav-section"><div class="nav-heading">Project Space</div>
   <button class="nav-row active" style="${toneStyle("core")}" onclick="openProjectSpace()"><span class="nav-icon">${icon("projects",19)}</span>Datum workspace</button>
   <button class="nav-row" style="${toneStyle("core")}" onclick="openTool('command','project')"><span class="nav-icon">${icon("dashboard",19)}</span>Command Centre</button>
   <button class="nav-row" style="${toneStyle("core")}"><span class="nav-icon">${icon("document",19)}</span>Project Passport</button>
   <button class="nav-row" style="${toneStyle("coral")}"><span class="nav-icon">${icon("inbox",19)}</span>Action Centre<span class="badge">7</span></button>
  </div>${toolGroups("project")}<div class="nav-note"><b>Project orientation:</b> tools inherit the project stage, roles, records, drawings and audit chain. Outputs dock back onto the datum.</div>`;
 }else{
  nav.innerHTML=`<div class="nav-head"><div class="kicker">Standalone workspace</div><div class="nav-title">Tool Library</div><div class="nav-sub">Use capabilities independently or across the portfolio.</div>${modeSwitch()}</div>
  <div class="nav-section"><div class="nav-heading">Quick Access</div>
   <button class="nav-row active" style="${toneStyle("lavender")}" onclick="openStandalone()"><span class="nav-icon">${icon("tools",19)}</span>All standalone tools</button>
   <button class="nav-row"><span class="nav-icon">${icon("search",19)}</span>Recent tools</button>
   <button class="nav-row"><span class="nav-icon">${icon("document",19)}</span>Unassigned drafts<span class="badge">9</span></button>
  </div>${toolGroups("standalone")}<div class="nav-note"><b>Standalone orientation:</b> the same tools run without a project. Attach a project later to unlock auto-fill, role routing and datum registration.</div>`;
 }
}
function toolGroups(mode){
 const groups={};Object.entries(TOOLS).filter(([id])=>id!=="command").forEach(([id,t])=>(groups[t.group]??=[]).push([id,t]));
 return Object.entries(groups).map(([g,items])=>`<div class="nav-section"><div class="nav-heading">${g}</div>${items.map(([id,t])=>`<button class="nav-row" style="${toneStyle(t.tone)}" onclick="openTool('${id}','${mode}')"><span class="nav-icon">${icon(t.icon,19)}</span>${t.name}</button>`).join("")}</div>`).join("");
}
function pageHead(title,sub,iconName,tone,actions=""){return `<div class="page-head"><div class="page-title-row"><div class="page-icon" style="${toneStyle(tone)}">${icon(iconName,26)}</div><div class="page-copy"><h1>${title}</h1><p>${sub}</p></div></div><div class="page-actions">${actions}</div></div>`}
function renderMain(){
 const main=q("#main");
 if(state.tool){const t=TOOLS[state.tool];main.innerHTML=`${pageHead(t.name,t.summary,t.icon,t.tone,`${state.mode==="standalone"?`<button class="btn" onclick="attachProject()">Attach ${project.name}</button>`:""}<button class="btn ghost" onclick="reloadTool()">Reload original sample</button>`)}
 <div class="tool-banner"><b>${state.mode==="project"?"Project-connected":"Standalone"} workspace</b><span>·</span><span>${state.mode==="project"?`Inputs and outputs stay linked to ${project.name}.`:"No project data is assumed; original tool project selectors remain available."}</span><span class="spacer"></span><span>Current Datum UI · original workflow preserved <span>·</span><span>Source: ${sourceName(state.tool)}</span></span></div>
 <div class="tool-shell loading" id="toolShell"><iframe class="tool-frame" id="toolFrame" title="${t.name} original functional sample"></iframe></div>`;setTimeout(()=>loadToolFrame(state.tool),0);return}
 if(state.global==="projects"){main.innerHTML=renderProjectSpace();return}
 if(state.global==="tools"){main.innerHTML=renderLibrary();return}
 main.innerHTML=renderGlobalPage(state.global);
}
function sourceName(id){return {command:"PROJECT_COMMAND_CENTRE_SAMPLE.html",wingman:"AI_COPILOT_WORKSPACE_WINGMAN_SAMPLE.html",bom:"BOM_TOOL_SAMPLE.html",safety:"HEALTH_SAFETY_MODULE_SAMPLE.html",itp:"ITP_WORKSPACE_SAMPLE.html",municipal:"MUNICIPAL_APPROVAL_WORKSPACE_SAMPLE.html",planning:"TOWN_PLANNING_PROTOTYPE.html",xa:"XA_COMPLIANCE_TOOL.html",specforge:"specforge-v2-review.html",forms:"Integrated Form System sample"}[id]}
function renderProjectSpace(){
 const stageList=["Brief","Appoint","Design","Comply","Procure","Build","Pay","Close-out"];
 const cards=[["planning","10%","13%"],["municipal","33%","13%"],["xa","56%","13%"],["forms","78%","13%"],["bom","16%","67%"],["specforge","39%","67%"],["itp","62%","67%"],["safety","82%","67%"]];
 const nodes=[14,27,39,51,63,75,87,94];
 return `${pageHead(project.name,"The datum is the project’s single line of truth. Tools open as project-connected workspaces and write their outputs back to this line.","projects","core",`<button class="btn ghost" onclick="openTool('wingman','project')">${icon("wingman",15)} Ask Wingman</button><button class="btn">${icon("attach",15)} Add project object</button>`)}
 <section class="project-hero"><div class="project-top"><div><h2>${project.name}</h2><p>${project.location} · ${project.client} · ${project.professional}</p></div><span class="status green">● In progress · ${project.progress}%</span></div><div class="stages">${stageList.map((s,i)=>`<div class="stage ${s===project.stage?"active":""}"><i>${i+1}</i><span>${s}</span></div>`).join("")}</div></section>
 <section class="datum-canvas"><div class="datum-line"></div><div class="datum-origin"><img src="${LOGO}" alt=""></div><div class="datum-label">DATUM<span>single line of truth</span></div>${nodes.map(x=>`<i class="datum-node" style="left:${x}%"></i>`).join("")}${cards.map((c,i)=>datumCard(c[0],c[1],c[2],i<4?"above":"below")).join("")}</section>`;
}
function datumCard(id,left,top,side){const t=TOOLS[id];const metrics={planning:["2 active applications","Next deadline 4 Aug"],municipal:["Readiness 82%","4 blockers"],xa:["7 / 9 components pass","Fenestration pending"],forms:["6 forms exported","2 signatures pending"],bom:["47 material lines","R1.86m estimate"],specforge:["64 sections","12 clauses flagged"],itp:["3 hold points","1 NCR linked"],safety:["Safety file 91%","0 lost-time incidents"]}[id];return `<article class="datum-card ${side}" style="left:${left};top:${top};${toneStyle(t.tone)}" onclick="openTool('${id}','project')"><div class="dc-head"><div class="dc-icon">${icon(t.icon,22)}</div><strong>${t.name}</strong></div><p>${t.summary}</p><div class="mini-row"><span>${metrics[0]}</span><span>›</span></div><div class="mini-row"><span>${metrics[1]}</span><span class="status ${metrics[1].match(/pending|block|flag/)?"amber":"green"}">${t.stage}</span></div></article>`}
function renderLibrary(){return `${pageHead("Standalone Tool Library","Open the same production tools outside a project. Project selectors and portfolio filters remain available inside the original module samples.","tools","lavender",`<button class="btn ghost" onclick="setMode('project')">Open project orientation</button>`)}<div class="notice"><b>One tool, two orientations.</b> Standalone mode does not create a duplicate app. It changes scope. Attach a project at any point and the tool becomes project-connected.</div><section class="tool-library">${Object.entries(TOOLS).filter(([id])=>id!=="command").map(([id,t])=>`<article class="lib-card" style="${toneStyle(t.tone)}" onclick="openTool('${id}','standalone')"><div class="lib-head"><div class="lib-icon">${icon(t.icon,25)}</div><div><strong>${t.name}</strong><div style="font-size:8px;color:${tones[t.tone]};margin-top:2px">${t.group}</div></div></div><p>${t.summary}</p><div class="lib-meta"><span>Original sample functionality</span><span class="status">Open tool ›</span></div></article>`).join("")}</section>`}
function renderGlobalPage(id){const item=globalItems.find(x=>x.id===id)||globalItems[0];return `${pageHead(item.label,"Platform-wide area represented in the global OS layer.",item.icon,item.tone)}<div class="panel panel-pad"><div class="notice">This prototype focuses on the datum project space and the integrated tool navigation. ${item.label} remains a global destination and would use the same shell.</div></div>`}

function decode64(s){const bin=atob(s);const bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);return new TextDecoder().decode(bytes)}
function reloadTool(){loadToolFrame(state.tool)}
function loadToolFrame(id){
 const frame=q("#toolFrame");if(!frame||!id)return;
 const shell=q("#toolShell");shell?.classList.add("loading");state.frameReady=false;
 let completed=false;
 const finalize=()=>{
  if(completed||!frame.contentDocument?.body||!frame.contentDocument.body.children.length)return false;
  completed=true;
  try{
   adaptFrame(id,frame);state.frameReady=true;shell?.classList.remove("loading");
   setTimeout(()=>invokeToolAction(TOOLS[id].tabs[state.toolTab]),120);
  }catch(e){console.error(e);shell?.classList.remove("loading")}
  return true;
 };
 frame.onload=finalize;
 frame.srcdoc=decode64(SOURCES[id]);
 let attempts=0;const probe=setInterval(()=>{attempts++;if(finalize()||attempts>30)clearInterval(probe)},100);
}
