[style*="color:#f1f5f9"],[style*="color: #f1f5f9"],[style*="color:#e2e8f0"],[style*="color: #e2e8f0"],[style*="color:#fafaf9"],[style*="color: #fafaf9"],[style*="color:#ffffff"],[style*="color: #ffffff"]{color:var(--ax-ink)!important}
