function adaptFrame(id,frame){
 const d=frame.contentDocument,w=frame.contentWindow;if(!d)return;
 d.documentElement.classList.remove('dark');
 d.body.classList.add('ax-tool-root');
 d.body.style.setProperty('--ax-tone',tones[TOOLS[id]?.tone]||'#19B7B0');
 const st=d.createElement('style');st.id='architex-datum-skin';st.textContent=commonFrameCss+(adapterCss[id]||'');d.head.appendChild(st);
 normalizeToolStructure(id,d,w);
 decorateToolIcons(id,d);
 installMutationSkin(id,d);
 applyOrientationAdapter(id,d,w);
}
function normalizeToolStructure(id,d,w){
 // Preserve every original control and script; only duplicate outer shells are hidden by CSS.
 if(id==='xa'){
  const wrap=[...d.body.children].find(x=>x.tagName==='DIV');
  if(wrap){const main=wrap.querySelector('main');if(main){main.style.width='100%';main.style.maxWidth='none';main.style.padding='16px'}}
 }
 // Add a subtle native context ribbon without interfering with module handlers.
 if(!d.querySelector('.ax-native-context')){
  const ribbon=d.createElement('div');ribbon.className='ax-native-context';
  ribbon.style.cssText='display:flex;align-items:center;gap:8px;margin:0 0 12px;padding:8px 11px;border:1px solid rgba(16,32,51,.09);border-radius:11px;background:rgba(255,255,255,.9);font:600 10px Inter,system-ui;color:#102033;position:relative;z-index:2';
  ribbon.innerHTML=`<span style="display:inline-flex;width:8px;height:8px;border-radius:50%;background:${tones[TOOLS[id]?.tone]||'#19B7B0'}"></span><span>${state.mode==='project'?'Project-connected':'Standalone'} ${TOOLS[id]?.name||'tool'}</span><span style="font-weight:400;color:#657287">${state.mode==='project'?project.name+' · '+project.stage+' stage':'Portfolio / unassigned · attach a project when required'}</span><span style="margin-left:auto;font-weight:700;color:#167E79">Original workflow active</span>`;
  const target=findToolContentRoot(id,d)||d.body.firstElementChild;
  if(target&&target!==d.body){target.insertBefore(ribbon,target.firstChild)}else d.body.insertBefore(ribbon,d.body.firstChild);
 }
}
function findToolContentRoot(id,d){
 const selectors={command:'.content',wingman:'.content',bom:'.main-content',safety:'.main-content',itp:'.workspace',municipal:'.content-area',planning:'.main-content',xa:'main',specforge:'.main-content',forms:'.content'};
 return d.querySelector(selectors[id]||'main');
}
function decorateToolIcons(id,d){
 const selectors=['.tc-icon','.dr-icon','.form-section-icon','.ac-icon','.advisor-icon','.icon','.nav-icon','.sf-num','.brand-icon','.wingman-avatar'];
 d.querySelectorAll(selectors.join(',')).forEach(el=>{
  if(el.dataset.axDecorated||el.closest('.ax-native-context')||el.matches('button')||el.querySelector('input,select,textarea'))return;
  const text=((el.closest('.template-card,.action-card,.card,.panel,.advisor-item,.form-section,.draft-row')||el.parentElement)?.textContent||'').toLowerCase();
  let name=TOOLS[id]?.icon||'document';
  if(/wingman|ai |copilot/.test(text))name='wingman';else if(/municip|council|approval|authority/.test(text))name='municipal';else if(/safety|incident|permit|hira/.test(text))name='safety';else if(/inspection|quality|test plan|checklist/.test(text))name='itp';else if(/specification|specforge|clause/.test(text))name='specification';else if(/bom|boq|material|procure|tender/.test(text))name='bom';else if(/form|document|drawing|pdf|file/.test(text))name='document';else if(/project|site|building/.test(text))name='projects';
  el.dataset.axDecorated='1';el.classList.add('ax-inline-icon');el.innerHTML=icon(name,18);
 });
 decorateActionIcons(id,d);
}
function decorateActionIcons(id,d){
 d.querySelectorAll('button,.btn,.action-btn,.ai-btn').forEach(btn=>{
  if(btn.dataset.axActionIcon||btn.closest('.ax-native-context')||btn.querySelector('.ax-action-icon')||btn.textContent.trim().length>42)return;
  const label=btn.textContent.trim().toLowerCase();if(!label)return;
  let name=null;
  if(/wingman|ask ai|ai |scan|suggest/.test(label))name='wingman';
  else if(/export|download|pdf|document|report|preview/.test(label))name='document';
  else if(/permit|incident|hazard|safety|fall protection|hira/.test(label))name='safety';
  else if(/approve|validate|check|complete|sign/.test(label))name='itp';
  else if(/municipal|council|submit|application/.test(label))name='municipal';
  else if(/procure|tender|bom|boq|material|quote/.test(label))name='bom';
  else if(/project|team|induction|collabor/.test(label))name='projects';
  else if(/add|new|create|import|upload/.test(label))name='attach';
  else if(/search|filter|find/.test(label))name='search';
  if(!name)return;
  for(const node of [...btn.childNodes])if(node.nodeType===3){node.textContent=node.textContent.replace(/^\s*[^A-Za-z0-9]+\s*/,'');break}
  const span=d.createElement('span');span.className='ax-action-icon';span.innerHTML=icon(name,16);btn.insertBefore(span,btn.firstChild);btn.dataset.axActionIcon='1';
  btn.style.display='inline-flex';btn.style.alignItems='center';btn.style.justifyContent=btn.style.justifyContent||'center';
 });
}
function installMutationSkin(id,d){
 const target=findToolContentRoot(id,d)||d.body;
 const observer=new MutationObserver(muts=>{
  let changed=false;for(const m of muts){if(m.addedNodes?.length){changed=true;break}}
  if(changed){if(!d.querySelector('.ax-native-context'))normalizeToolStructure(id,d,d.defaultView);decorateToolIcons(id,d);d.body.style.setProperty('--ax-tone',tones[TOOLS[id]?.tone]||'#19B7B0')}
 });
 observer.observe(target,{childList:true,subtree:true});
 d.defaultView.__architexSkinObserver=observer;
}
function applyOrientationAdapter(id,d,w){
 if(state.mode==='standalone'){
  try{
   if(id==='planning'&&typeof w.setMode==='function')w.setMode('standalone');
   if(id==='bom'&&typeof w.selectProject==='function')w.selectProject('New Project');
   if(id==='safety'){const b=[...d.querySelectorAll('button')].find(x=>x.textContent.includes('All Projects'));b?.click()}
   if(id==='itp'){const b=[...d.querySelectorAll('button')].find(x=>x.textContent.trim()==='All Projects');b?.click()}
  }catch(e){console.warn('orientation adapter',e)}
 }else{
  try{if(id==='planning'&&typeof w.setMode==='function')w.setMode('project')}catch(e){}
 }
}
function invokeToolAction(action){
 const frame=q("#toolFrame");if(!frame||!frame.contentWindow||!action)return;const w=frame.contentWindow,d=frame.contentDocument;
 try{
  if(action.kind==="top"){w.scrollTo({top:0,behavior:"smooth"});return}
  if(action.kind==="call"){
   const fn=w[action.fn];if(typeof fn==="function"){action.arg===undefined?fn():fn(action.arg);return}
  }
  if(action.kind==="hs"){
   const el=d.getElementById(action.arg);const btn=[...d.querySelectorAll(".tab")].find(x=>x.getAttribute("onclick")?.includes(action.arg));if(typeof w.activateTab==="function")w.activateTab(btn||d.querySelector(".tab"),action.arg);else el?.scrollIntoView({behavior:"smooth",block:"start"});return
  }
  if(action.kind==="scroll"){scrollFrameToText(d,w,action.text);return}
 }catch(e){console.warn("tool action failed",e)}
}
function scrollFrameToText(d,w,text){
 const els=[...d.querySelectorAll("h1,h2,h3,h4,button,.card-title,.section-title,.stat-label")];const target=els.find(x=>x.textContent.trim().toLowerCase().includes(text.toLowerCase()));
 if(target){target.scrollIntoView({behavior:"smooth",block:"start"});const box=target.closest(".card,.panel,.section,.content")||target;box.animate([{outline:"2px solid rgba(25,183,176,.0)"},{outline:"2px solid rgba(25,183,176,.55)"},{outline:"2px solid rgba(25,183,176,.0)"}],{duration:900})}
 else w.scrollTo({top:0,behavior:"smooth"});
}
function renderInspector(){
 const t=state.tool?TOOLS[state.tool]:null;q("#inspectTitle").textContent=t?t.name:(state.mode==="project"?"Project context":"Standalone context");q("#inspectSub").textContent=state.mode==="project"?project.name:"Portfolio / unassigned";const body=q("#inspectBody");
 if(state.inspector==="wingman"){body.innerHTML=`<div class="inspect-note"><b>Wingman uses the current scope.</b><br>${state.mode==="project"?"The active project, module view and selected records form its working context.":"Only selected portfolio records or uploads are assumed."}</div><div class="inspect-block"><h4>Suggested prompts</h4>${["Summarise current blockers","Draft the next required communication","Explain the active compliance issue","Create an action from this item"].map(x=>`<div class="ai-card">${x}</div>`).join("")}</div><button class="btn dark" style="width:100%" onclick="openTool('wingman',state.mode)">Open full Wingman workspace</button>`;return}
 if(state.inspector==="activity"){body.innerHTML=`<div class="inspect-block"><h4>Recent activity</h4>${["Justin opened the workspace","M. Patel added a review comment","System linked a revised drawing","Wingman created an action"].map((x,i)=>`<div class="activity-row"><div class="activity-dot">${["JK","MP","↻","AI"][i]}</div><div class="activity-copy"><b>${x}</b><span>${i+1} hour${i?"s":""} ago</span></div></div>`).join("")}</div>`;return}
 if(t){body.innerHTML=`<div class="inspect-note">${state.mode==="project"?`This original <b>${t.name}</b> sample is running inside the ${project.name} project shell. Its internal functionality is preserved while global and tool navigation are supplied by Datum OS.`:`This original <b>${t.name}</b> sample is running standalone. Its own project selectors remain available where the sample supports them.`}</div><div class="inspect-block"><h4>Scope</h4><p><b>${state.mode==="project"?"Project-connected":"Standalone"}</b><br>${state.mode==="project"?project.location:"Portfolio and unassigned work"}</p></div><div class="inspect-block"><h4>Module relationship</h4><p>${t.summary}<br><br><b>Relevant stages:</b> ${t.stage}<br><b>Module tone:</b> ${t.tone}</p></div><div class="inspect-block"><h4>Navigation contract</h4><p>The far-left rail selects the platform destination. The second panel selects project or tool context. These entries drive the supplied module’s real internal functions in the central frame.</p></div>${state.mode==="standalone"?`<button class="btn" style="width:100%" onclick="attachProject()">Attach ${project.name}</button>`:""}`;return}
 body.innerHTML=`<div class="inspect-note">${state.mode==="project"?`The datum is the <b>single line of truth</b>. Every attached tool is a view onto the project, not an isolated application.`:`Standalone tools use the same modules without a project scope.`}</div><div class="inspect-block"><h4>Four navigation layers</h4><p><b>1. Global OS rail</b> — platform destination.<br><b>2. Context navigator</b> — project, tool and orientation.<br><b>3. Central module</b> — original functional workspace.<br><b>4. Right inspector</b> — context, Wingman and activity.</p></div><div class="inspect-block"><h4>Current scope</h4><p>${state.mode==="project"?`${project.name}<br>${project.stage} stage · ${project.progress}% complete<br>${project.municipality}`:"Portfolio-wide<br>No project assumed<br>Unassigned drafts permitted"}</p></div>`;
}

