function iconForTab(tab,fallback){
 if(tab?.icon&&iconShapes[tab.icon])return tab.icon;
 const l=(tab?.label||'').toLowerCase();
 const map=[
  [/overview|dashboard/,'dashboard'],[/progress/,'progress'],[/budget|cost|payment|fee/,'budget'],[/action|task/,'action'],[/rfi|instruction/,'rfi'],[/programme|calendar|deadline|timeline/,'programme'],[/advisor|ai |agent|wingman/,'advisor'],[/milestone/,'milestone'],[/cluster/,'clusters'],[/trend|analytics|report/,'trends'],[/detail|audit|history/,'detail'],[/workflow|status|approval/,'workflow'],[/team|resource|collabor/,'team_workspace'],[/document|drawing|pdf|export|preview/,'documents_drawings'],[/form|template|draft|editor/,'forms'],[/municip|council|land use|circulation|submission/,'municipal'],[/safety|hira|permit|incident|induction|fall/,'safety'],[/inspection|test|quality|hold|lab|ncr|sign/,'itp'],[/procure|tender|bom|boq|material|quote/,'bom'],[/spec|product|section|pictorial/,'specification'],[/planning|application|condition|hearing|participation/,'planning'],[/message|conversation|notification/,'inbox'],[/integration|link|sync/,'integration']
 ];
 for(const [rx,key] of map)if(rx.test(l))return key;
 return fallback||'brief';
}

function renderGlobalMenu(){
 q('#globalMenu').innerHTML=globalItems.map(i=>`<button class="os-item ${state.global===i.id?'active':''}" style="${toneStyle(i.tone)}" onclick="openGlobal('${i.id}')" aria-label="${i.label}" data-tooltip="${i.label}" title="${i.label}"><span class="icon-wrap">${icon(i.icon,25)}</span><span class="os-label">${i.label}</span><span class="os-meta">${i.meta}</span></button>`).join('');
}
function toggleNavigator(){q('#app').classList.toggle('nav-compact');renderTopbar()}
function openGlobal(id){state.global=id;state.toolTab=0;if(id==='projects'){state.mode='project';state.tool=null}else if(id==='tools'){state.mode='standalone';state.tool=null}else if(id==='feedback'){state.mode='standalone';state.tool='feedback'}else{state.tool=null}renderAll()}
function setToolTab(index){state.toolTab=index;renderNavigator();if(TOOLS[state.tool]?.status==='scaffold')renderMain();else invokeToolAction(TOOLS[state.tool].tabs[index]);renderInspector();updateFeedbackContext()}
function sourceName(id){return TOOLS[id]?.source||'Integration scaffold'}
function toolGroups(mode){
 const groups={};Object.entries(TOOLS).forEach(([id,t])=>(groups[t.group]??=[]).push([id,t]));
 return Object.entries(groups).map(([g,items])=>`<div class="nav-section"><div class="nav-heading">${g}</div>${items.map(([id,t])=>`<button class="nav-row" style="${toneStyle(t.tone)}" onclick="openTool('${id}','${mode}')" title="${t.name}"><span class="nav-icon">${icon(t.icon,21)}</span><span class="nav-label">${t.name}</span>${t.status==='scaffold'?'<span class="badge">Scaffold</span>':''}</button>`).join('')}</div>`).join('');
}
function renderNavigator(){
 const nav=q('#navigator');
 if(state.tool){const t=TOOLS[state.tool];nav.innerHTML=`<div class="nav-head"><div class="nav-compact-mark" title="${t.name}">${icon(t.icon,27)}</div><div class="kicker">${state.mode==='project'?'Project tool':'Standalone tool'}</div><div class="nav-title">${t.name}</div><div class="nav-sub">${state.mode==='project'?project.name+' · '+project.stage+' stage':'Portfolio-wide workspace · project optional'}</div>${modeSwitch()}${state.mode==='project'?`<select class="project-select" name="projectSelector" aria-label="Active project"><option>${project.name}</option><option>Camps Bay Residence</option><option>12 Riverside Ave</option></select>`:''}</div><div class="back-row" onclick="${state.mode==='project'?'openProjectSpace()':'openStandalone()'}" title="${state.mode==='project'?'Back to datum project space':'Back to standalone library'}">${icon('projects',18)}<span class="nav-label">${state.mode==='project'?'Back to datum project space':'Back to standalone library'}</span></div><div class="nav-section"><div class="nav-heading">Inside ${t.name}</div>${t.tabs.map((x,i)=>`<button class="nav-row ${state.toolTab===i?'active':''}" style="${toneStyle(t.tone)}" onclick="setToolTab(${i})" title="${x.label}"><span class="nav-icon">${icon(iconForTab(x,t.icon),21)}</span><span class="nav-label">${x.label}</span>${x.badge?`<span class="badge">${x.badge}</span>`:''}</button>`).join('')}</div><div class="nav-note"><b>${t.status==='live'?'Functional sample preserved.':'Integration scaffold.'}</b><br>${t.status==='live'?'This navigation drives the supplied module sample in the central workspace.':'The navigation, context, data and permissions contract is reserved until the functional sample is integrated.'}</div>`;return}
 const mark=state.mode==='project'?'projects':'tools';
 if(state.mode==='project')nav.innerHTML=`<div class="nav-head"><div class="nav-compact-mark" title="${project.name}">${icon(mark,27)}</div><div class="kicker">Active project</div><div class="nav-title">${project.name}</div><div class="nav-sub">${project.location} · ${project.stage} stage · Rev ${project.revision}</div>${modeSwitch()}<select class="project-select" name="projectSelector" aria-label="Active project"><option>${project.name}</option><option>Camps Bay Residence</option><option>12 Riverside Ave</option></select></div><div class="nav-section"><div class="nav-heading">Project Space</div><button class="nav-row active" style="${toneStyle('core')}" onclick="openProjectSpace()" title="Datum workspace"><span class="nav-icon">${icon('projects',21)}</span><span class="nav-label">Datum workspace</span></button><button class="nav-row" style="${toneStyle('cobalt')}" onclick="openTool('practice','project')" title="Practice Management — Project Command Centre"><span class="nav-icon">${icon('practice_management',21)}</span><span class="nav-label">Practice / Project Command Centre</span></button><button class="nav-row" style="${toneStyle('core')}" onclick="openTool('project_passport','project')" title="Project Passport"><span class="nav-icon">${icon('project_passport',21)}</span><span class="nav-label">Project Passport</span><span class="badge">Scaffold</span></button><button class="nav-row" style="${toneStyle('coral')}" onclick="openTool('inbox_action','project')" title="Inbox / Action Centre"><span class="nav-icon">${icon('action_centre',21)}</span><span class="nav-label">Action Centre</span><span class="badge">7</span></button></div>${toolGroups('project')}<div class="nav-note"><b>Project orientation:</b> tools inherit the project stage, roles, records, drawings and audit chain. Outputs dock back onto the datum.</div>`;
 else nav.innerHTML=`<div class="nav-head"><div class="nav-compact-mark" title="Workspace Tools">${icon(mark,27)}</div><div class="kicker">Standalone workspace</div><div class="nav-title">Workspace Tool Registry</div><div class="nav-sub">Every current and planned capability is listed. Live samples retain their workflows; scaffolds reserve integration contracts.</div>${modeSwitch()}</div><div class="nav-section"><div class="nav-heading">Quick Access</div><button class="nav-row active" style="${toneStyle('lavender')}" onclick="openStandalone()" title="All workspace tools"><span class="nav-icon">${icon('tools',21)}</span><span class="nav-label">All workspace tools</span><span class="badge">${Object.keys(TOOLS).length}</span></button><button class="nav-row" onclick="openTool('feedback','standalone')" title="Feedback Intelligence"><span class="nav-icon">${icon('feedback',21)}</span><span class="nav-label">Feedback Intelligence</span></button></div>${toolGroups('standalone')}<div class="nav-note"><b>Standalone orientation:</b> the same tools run without a project. Attach a project later to unlock auto-fill, role routing and datum registration.</div>`;
}
function renderTopbar(){
 q('#navToggle').innerHTML=icon('menu',20);q('#navToggle').title=q('#app').classList.contains('nav-compact')?'Expand context navigation':'Minimise context navigation';q('#wingmanTop').innerHTML=icon('wingman',20);q('#wingmanTop').title='Open Wingman';q('#inspectToggle').innerHTML=icon('inspector',20);q('#inspectToggle').title='Toggle contextual inspector';q('#scopePill').textContent=state.mode==='project'?'Project orientation':'Standalone orientation';q('#projectChip').textContent=state.mode==='project'?'● '+project.name:'○ Portfolio / unassigned';let crumb='Architex OS › ';if(state.tool)crumb+=(state.mode==='project'?`Projects › ${project.name} › `:'Workspace Tools › ')+`<b>${TOOLS[state.tool].name}</b>`;else if(state.global==='projects')crumb+=`Projects › <b>${project.name}</b>`;else crumb+=`<b>${globalItems.find(x=>x.id===state.global)?.label||'Workspace'}</b>`;q('#breadcrumb').innerHTML=crumb;updateFeedbackContext();
}
function renderMain(){
 const main=q('#main');
 if(state.tool){const t=TOOLS[state.tool];if(t.status==='scaffold'){main.innerHTML=`${pageHead(t.name,t.summary,t.icon,t.tone,`${state.mode==='standalone'?`<button class="btn" onclick="attachProject()">Attach ${project.name}</button>`:''}<button class="btn ghost" onclick="showToast('Scaffold retained for the developer briefing pack.')">Add implementation note</button>`)}<div class="tool-banner"><b>${state.mode==='project'?'Project-connected':'Standalone'} scaffold</b><span>·</span><span>${state.mode==='project'?`Reserved against ${project.name}.`:'Available portfolio-wide before a project is attached.'}</span><span class="spacer"></span><span>Awaiting functional sample integration</span></div>${renderScaffold(t)}`;return}
 main.innerHTML=`${pageHead(t.name,t.summary,t.icon,t.tone,`${state.mode==='standalone'?`<button class="btn" onclick="attachProject()">Attach ${project.name}</button>`:''}<button class="btn ghost" onclick="reloadTool()">Reload functional sample</button>`)}<div class="tool-banner"><b>${state.mode==='project'?'Project-connected':'Standalone'} workspace</b><span>·</span><span>${state.mode==='project'?`Inputs and outputs stay linked to ${project.name}.`:'No project data is assumed; original project selectors remain available.'}</span><span class="spacer"></span><span>Datum UI skin · workflow preserved · Source: ${sourceName(state.tool)}</span></div><div class="tool-shell loading" id="toolShell"><iframe class="tool-frame" id="toolFrame" title="${t.name} functional sample"></iframe></div>`;setTimeout(()=>loadToolFrame(state.tool),0);return}
 if(state.global==='projects'){main.innerHTML=renderProjectSpace();return}if(state.global==='tools'){main.innerHTML=renderLibrary();return}main.innerHTML=renderGlobalPage(state.global);
}
function renderScaffold(t){
 const active=t.tabs[state.toolTab]||t.tabs[0];const orientation=state.mode==='project'?'project':'standalone';
 const copy={
  'Workspace Brief':['Purpose and user outcome',t.summary,'Primary roles and permissions will be mapped before the functional module is mounted.'],
  'Project Orientation':['Project-connected behaviour',`The tool opens from the datum and inherits ${project.name}, the ${project.stage} stage, project roles, records and audit history.`,'Outputs register back to project objects and become available to Wingman and dependent modules.'],
  'Standalone Orientation':['Portfolio / unassigned behaviour','The same capability opens without assuming a project. Users may select records, upload data or create an unassigned draft.','Attaching a project changes scope without creating a second tool implementation.'],
  'Integration Contract':['Developer integration contract','Mount the existing feature component inside the Datum OS shell. Remove only duplicate outer navigation and preserve business logic, service calls and validation.','Map the tool icon, tone, routes, permissions, project context, standalone context, audit events and feedback context.']
 }[active.label]||['Workspace scaffold',t.summary,'Awaiting implementation sample.'];
 return `<section class="scaffold-shell" style="${toneStyle(t.tone)}"><div class="scaffold-hero"><div style="display:flex;align-items:center;gap:13px"><div class="page-icon" style="${toneStyle(t.tone)}">${icon(t.icon,28)}</div><div><span class="status" style="color:var(--lavender);background:rgba(139,92,246,.08)">Integration scaffold</span><h2>${copy[0]}</h2></div></div><p>${copy[1]}</p><p>${copy[2]}</p><div class="scaffold-contract"><div class="contract-chip"><b>Orientation</b>${orientation}</div><div class="contract-chip"><b>Stage</b>${t.stage}</div><div class="contract-chip"><b>Module group</b>${t.group}</div><div class="contract-chip"><b>Source</b>Awaiting sample</div></div></div><div class="scaffold-grid"><article class="scaffold-card"><h3>Inputs to reserve</h3><ul><li>Authenticated user and role</li><li>Optional project and current work stage</li><li>Project Passport records and linked documents</li><li>Module-specific permissions and organisation scope</li></ul></article><article class="scaffold-card"><h3>Outputs to register</h3><ul><li>Project object and datum activity event</li><li>Action Centre notifications and approvals</li><li>Document Register or structured data record</li><li>Wingman-readable context and audit history</li></ul></article><article class="scaffold-card"><h3>UI contract</h3><p>Use the shared Datum surfaces, readable type scale, rounded-origami icon, module tone outside the icon, central workspace and contextual right inspector.</p></article><article class="scaffold-card"><h3>Functional contract</h3><p>Do not rewrite the tool’s business logic. Preserve calculations, validation, dialogs, APIs, state and workflows while replacing only its outer shell and visual tokens.</p></article></div></section>`;
}
function renderProjectSpace(){
 const stageList=['Brief','Appoint','Design','Comply','Procure','Build','Pay','Close-out'];
 const cards=[['practice','3%','11%'],['planning','23%','11%'],['municipal','43%','11%'],['xa','63%','11%'],['forms','80%','11%'],['bom','13%','68%'],['specforge','35%','68%'],['itp','57%','68%'],['safety','78%','68%']];
 const nodes=[10,21,32,43,54,65,76,87,96];
 return `${pageHead(project.name,"The datum is the project’s single line of truth. Live tools open as project-connected workspaces; planned capabilities are already reserved in the registry below.",'projects','core',`<button class="btn ghost" onclick="openTool('wingman','project')">${icon('wingman',16)} Ask Wingman</button><button class="btn" onclick="toggleFeedback(true)">${icon('feedback',16)} Give feedback</button>`)}<section class="project-hero"><div class="project-top"><div><h2>${project.name}</h2><p>${project.location} · ${project.client} · ${project.professional}</p></div><span class="status green">● In progress · ${project.progress}%</span></div><div class="stages">${stageList.map((x,i)=>`<div class="stage ${x===project.stage?'active':''}"><i>${i+1}</i><span>${x}</span></div>`).join('')}</div></section><section class="datum-canvas"><div class="datum-line"></div><div class="datum-origin"><img src="${LOGO}" alt="Architex bird"></div><div class="datum-label">DATUM<span>single line of truth</span></div>${nodes.map(x=>`<i class="datum-node" style="left:${x}%"></i>`).join('')}${cards.map((c,i)=>datumCard(c[0],c[1],c[2],i<5?'above':'below')).join('')}</section>${renderRegistry('project')}`;
}
function datumCard(id,left,top,side){const t=TOOLS[id];const metric={practice:['68% overall progress','14 open actions'],planning:['2 active applications','Next deadline 4 Aug'],municipal:['Readiness 82%','4 blockers'],xa:['7 / 9 components pass','Fenestration pending'],forms:['6 forms exported','2 signatures pending'],bom:['47 material lines','R1.86m estimate'],specforge:['64 sections','12 clauses flagged'],itp:['3 hold points','1 NCR linked'],safety:['Safety file 91%','0 lost-time incidents']}[id]||['Project-connected','Live workspace'];return `<article class="datum-card ${side}" style="left:${left};top:${top};${toneStyle(t.tone)}" onclick="openTool('${id}','project')"><div class="dc-head"><div class="dc-icon">${icon(t.icon,23)}</div><strong>${t.name}</strong></div><p>${t.summary}</p><div class="mini-row"><span>${metric[0]}</span><span>›</span></div><div class="mini-row"><span>${metric[1]}</span><span class="status ${metric[1].match(/pending|block|flag|open/) ? 'amber':'green'}">${t.stage}</span></div></article>`}
function renderRegistry(mode){const groups={};Object.entries(TOOLS).forEach(([id,t])=>(groups[t.group]??=[]).push([id,t]));return `<section style="margin-top:22px"><div class="page-head" style="margin-bottom:8px"><div class="page-copy"><h1 style="font-size:22px">Complete workspace tool registry</h1><p>Live modules and future integration scaffolds share one navigation, context and iconography contract.</p></div></div>${Object.entries(groups).map(([group,items])=>`<div class="registry-group"><h3 class="registry-heading">${group}<span>${items.length} tools</span></h3><div class="registry-grid">${items.map(([id,t])=>`<button class="registry-item ${t.status==='scaffold'?'scaffold':''}" style="${toneStyle(t.tone)}" onclick="openTool('${id}','${mode}')"><span class="nav-icon">${icon(t.icon,23)}</span><span><b>${t.name}</b><small>${t.stage}</small></span><span class="registry-status ${t.status==='scaffold'?'scaffold':''}">${t.status==='live'?'Live sample':'Scaffold'}</span></button>`).join('')}</div></div>`).join('')}</section>`}
function renderLibrary(){return `${pageHead('Workspace Tool Registry','Every current and planned tool is represented. Live samples retain their original workflow; scaffolds define how the missing modules will mount into Datum OS.','tools','lavender',`<button class="btn ghost" onclick="setMode('project')">Open project orientation</button>`)}<div class="notice"><b>One capability, two orientations.</b> Standalone and project modes share the same implementation. Scope, data sources and output registration change; the tool does not duplicate.</div>${renderRegistry('standalone')}`}
function renderGlobalPage(id){const item=globalItems.find(x=>x.id===id)||globalItems[0];if(id==='command')return `${pageHead('Architex OS Command Centre','The global landing point for work across projects, tools, actions and feedback. This is distinct from the full Practice Management / Project Command Centre tool.','dashboard','core')}<div class="scaffold-grid"><article class="scaffold-card" onclick="openProjectSpace()" style="cursor:pointer"><div class="lib-head"><div class="lib-icon">${icon('projects',26)}</div><h3>Open datum project space</h3></div><p>Enter ${project.name} and work through the project’s single line of truth.</p></article><article class="scaffold-card" onclick="openTool('practice','project')" style="cursor:pointer"><div class="lib-head"><div class="lib-icon">${icon('practice_management',26)}</div><h3>Practice / Project Command Centre</h3></div><p>Open the full supplied operational command centre as a separate tool.</p></article><article class="scaffold-card" onclick="openStandalone()" style="cursor:pointer"><div class="lib-head"><div class="lib-icon">${icon('tools',26)}</div><h3>Workspace tool registry</h3></div><p>Browse ${Object.keys(TOOLS).length} live and scaffolded capabilities.</p></article><article class="scaffold-card" onclick="openTool('feedback','standalone')" style="cursor:pointer"><div class="lib-head"><div class="lib-icon">${icon('feedback',26)}</div><h3>Feedback intelligence</h3></div><p>Review the product feedback loop and roadmap pipeline.</p></article></div>`;return `${pageHead(item.label,'Platform-wide area represented in the global OS layer.',item.icon,item.tone)}<div class="panel panel-pad"><div class="notice">${item.label} remains a global destination and will use the same shell, iconography, readable type scale and context rules.</div></div>`}
function loadToolFrame(id){const frame=q('#toolFrame');if(!frame||!id||!SOURCES[id])return;const shell=q('#toolShell');shell?.classList.add('loading');state.frameReady=false;let completed=false;const finalize=()=>{if(completed||!frame.contentDocument?.body||!frame.contentDocument.body.children.length)return false;completed=true;try{adaptFrame(id,frame);state.frameReady=true;shell?.classList.remove('loading');setTimeout(()=>invokeToolAction(TOOLS[id].tabs[state.toolTab]),150)}catch(e){console.error(e);shell?.classList.remove('loading')}return true};frame.onload=finalize;frame.srcdoc=decode64(SOURCES[id]);let attempts=0;const probe=setInterval(()=>{attempts++;if(finalize()||attempts>40)clearInterval(probe)},100)}
adapterCss.practice=`.sidebar,.top-bar{display:none!important}.main{display:block!important;min-height:0!important;background:transparent!important}.content{padding:20px!important;overflow:visible!important}.stat-row{gap:14px!important}.two-col{gap:16px!important}`;
adapterCss.feedback=`.os-nav,.tool-nav,.top-bar,.feedback-trigger,.feedback-overlay{display:none!important}.app-shell{display:block!important;min-height:100vh!important}.content{padding:20px!important;overflow:visible!important}.stat-grid{gap:14px!important}.cluster-row{grid-template-columns:minmax(280px,1fr) 90px 90px 120px 70px 110px!important}`;
function findToolContentRoot(id,d){const selectors={practice:'.content',feedback:'.content',wingman:'.content',bom:'.main-content',safety:'.main-content',itp:'.workspace',municipal:'.content-area',planning:'.main-content',xa:'main',specforge:'.main-content',forms:'.content'};return d.querySelector(selectors[id]||'main')}
function normalizeToolStructure(id,d,w){if(id==='xa'){const wrap=[...d.body.children].find(x=>x.tagName==='DIV');if(wrap){const main=wrap.querySelector('main');if(main){main.style.width='100%';main.style.maxWidth='none';main.style.padding='20px'}}}if(!d.querySelector('.ax-native-context')){const ribbon=d.createElement('div');ribbon.className='ax-native-context';ribbon.style.cssText='display:flex;align-items:center;gap:9px;margin:0 0 16px;padding:11px 13px;border:1px solid rgba(16,32,51,.09);border-radius:12px;background:rgba(255,255,255,.94);font:650 13px Inter,system-ui;color:#102033;position:relative;z-index:2';ribbon.innerHTML=`<span style="display:inline-flex;width:9px;height:9px;border-radius:50%;background:${tones[TOOLS[id]?.tone]||'#19B7B0'}"></span><span>${state.mode==='project'?'Project-connected':'Standalone'} ${TOOLS[id]?.name||'tool'}</span><span style="font-weight:400;color:#657287">${state.mode==='project'?project.name+' · '+project.stage+' stage':'Portfolio / unassigned · attach a project when required'}</span><span style="margin-left:auto;font-weight:750;color:#167E79">Functional workflow active</span>`;const target=findToolContentRoot(id,d)||d.body.firstElementChild;if(target&&target!==d.body)target.insertBefore(ribbon,target.firstChild);else d.body.insertBefore(ribbon,d.body.firstChild)}}
const v5FrameCss=`
html,body{font-size:16px!important;line-height:1.55!important}body,.ax-tool-root{font-size:16px!important}h1,.page-title,.header-title{font-size:29px!important}h2,.card-title,.panel-title{font-size:20px!important}h3,.form-section-title,.advisor-item-title,.milestone-title{font-size:17px!important}p,.sub,.header-meta,.stat-label,.stat-sub,.tc-meta,.dr-meta,.field-label,.audit-time,.meta,.project-meta,.breadcrumb,.form-label,.advisor-item-desc{font-size:14px!important;line-height:1.55!important}button,.btn,.action-btn,.ai-btn,.tab,.tab-btn,.tab-trigger,.library-tab,.nav-item,.tool-nav-item{font-size:14px!important;min-height:36px!important}input,select,textarea,.field-input,.form-input,.form-select,.form-textarea{font-size:15px!important;min-height:39px!important}table th,.table th{font-size:12px!important}table td,.table td{font-size:14px!important;line-height:1.45!important}.pill,.badge,.role-badge,.status-badge{font-size:12px!important}.stat-value{font-size:25px!important}.ax-native-context{font-size:13px!important}[style*="font-size:9px"],[style*="font-size: 9px"],[style*="font-size:10px"],[style*="font-size: 10px"]{font-size:12.5px!important}[style*="font-size:11px"],[style*="font-size: 11px"]{font-size:13px!important}[style*="font-size:12px"],[style*="font-size: 12px"]{font-size:14px!important}[style*="font-size:13px"],[style*="font-size: 13px"]{font-size:15px!important}`;
function adaptFrame(id,frame){const d=frame.contentDocument,w=frame.contentWindow;if(!d)return;d.documentElement.classList.remove('dark');d.body.classList.add('ax-tool-root');d.body.style.setProperty('--ax-tone',tones[TOOLS[id]?.tone]||'#19B7B0');const st=d.createElement('style');st.id='architex-datum-skin';st.textContent=commonFrameCss+v5FrameCss+(adapterCss[id]||'');d.head.appendChild(st);normalizeToolStructure(id,d,w);decorateToolIcons(id,d);installMutationSkin(id,d);applyOrientationAdapter(id,d,w)}
function renderInspector(){const t=state.tool?TOOLS[state.tool]:null;q('#inspectTitle').textContent=t?t.name:(state.mode==='project'?'Project context':'Standalone context');q('#inspectSub').textContent=state.mode==='project'?project.name:'Portfolio / unassigned';const body=q('#inspectBody');if(state.inspector==='wingman'){body.innerHTML=`<div class="inspect-note"><b>Wingman uses the current scope.</b><br>${state.mode==='project'?'The active project, module view and selected records form its working context.':'Only selected portfolio records or uploads are assumed.'}</div><div class="inspect-block"><h4>Suggested prompts</h4>${['Summarise current blockers','Draft the next required communication','Explain the active compliance issue','Create an action from this item'].map(x=>`<div class="ai-card">${x}</div>`).join('')}</div><button class="btn dark" style="width:100%" onclick="openTool('wingman',state.mode)">Open full Wingman workspace</button>`;return}if(state.inspector==='activity'){body.innerHTML=`<div class="inspect-block"><h4>Recent activity</h4>${['Justin opened the workspace','M. Patel added a review comment','System linked a revised drawing','Wingman created an action'].map((x,i)=>`<div class="activity-row"><div class="activity-dot">${['JK','MP','↻','AI'][i]}</div><div class="activity-copy"><b>${x}</b><span>${i+1} hour${i?'s':''} ago</span></div></div>`).join('')}</div>`;return}if(t){body.innerHTML=`<div class="inspect-note">${t.status==='live'?`The supplied <b>${t.name}</b> workflow is mounted inside Datum OS. Its business logic and controls remain intact while the shared shell supplies context and navigation.`:`<b>${t.name}</b> is reserved as an integration scaffold so navigation, iconography, project scope and standalone scope can be agreed before its sample is supplied.`}</div><div class="inspect-block"><h4>Scope</h4><p><b>${state.mode==='project'?'Project-connected':'Standalone'}</b><br>${state.mode==='project'?project.location:'Portfolio and unassigned work'}</p></div><div class="inspect-block"><h4>Module relationship</h4><p>${t.summary}<br><br><b>Relevant stages:</b> ${t.stage}<br><b>Status:</b> ${t.status==='live'?'Functional sample integrated':'Scaffold awaiting sample'}</p></div><div class="inspect-block"><h4>Feedback context</h4><p>The global feedback loop captures this tool, orientation, project and current internal section automatically.</p></div>${state.mode==='standalone'?`<button class="btn" style="width:100%" onclick="attachProject()">Attach ${project.name}</button>`:''}`;return}body.innerHTML=`<div class="inspect-note">${state.mode==='project'?`The datum is the <b>single line of truth</b>. Every attached tool is a view onto the project, not an isolated application.`:'Standalone tools use the same modules without a project scope.'}</div><div class="inspect-block"><h4>Navigation layers</h4><p><b>Global OS rail</b> — platform destination.<br><b>Context navigator</b> — project, tool and orientation.<br><b>Central workspace</b> — functional module or scaffold.<br><b>Inspector</b> — context, Wingman and activity.<br><b>Feedback loop</b> — context-aware product feedback everywhere.</p></div><div class="inspect-block"><h4>Current scope</h4><p>${state.mode==='project'?`${project.name}<br>${project.stage} stage · ${project.progress}% complete<br>${project.municipality}`:'Portfolio-wide<br>No project assumed<br>Unassigned drafts permitted'}</p></div>`}

/* Functional global feedback loop */
let feedbackCategory='Feature request',feedbackTab='submit';const feedbackRecords=[{title:'Improve datum card spacing',status:'Reviewing',date:'Today'},{title:'Add Excel export to BoQ',status:'Planned',date:'2 Jul 2026'}];
function initFeedback(){q('#feedbackFab').innerHTML=icon('feedback',27);q('#feedbackHeadIcon').innerHTML=icon('feedback',25);renderFeedbackCategories();renderFeedbackRecords();updateFeedbackContext();document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.shiftKey&&e.key.toLowerCase()==='f'){e.preventDefault();toggleFeedback()}})}
function toggleFeedback(force){const p=q('#feedbackPanel');const open=typeof force==='boolean'?force:!p.classList.contains('open');p.classList.toggle('open',open);if(open){updateFeedbackContext();setTimeout(()=>q('#feedbackText')?.focus(),80)}}
function setFeedbackTab(tab,el){feedbackTab=tab;qa('[data-feedback-tab]').forEach(x=>x.classList.remove('active'));el.classList.add('active');q('#feedbackSubmitView').style.display=tab==='submit'?'block':'none';q('#feedbackMineView').style.display=tab==='mine'?'block':'none';if(tab==='mine')renderFeedbackRecords()}
function renderFeedbackCategories(){const cats=[['Bug','ncr_manager'],['Feature request','advisor'],['Usability','iconography_registry'],['Praise','milestone']];q('#feedbackCategories').innerHTML=cats.map(([label,key])=>`<button class="feedback-category ${label===feedbackCategory?'selected':''}" onclick="selectFeedbackCategory('${label}')">${icon(key,20)}<span>${label}</span></button>`).join('')}
function selectFeedbackCategory(label){feedbackCategory=label;renderFeedbackCategories()}
function updateFeedbackCount(){const v=q('#feedbackText')?.value||'';q('#feedbackCount').textContent=`${v.length.toLocaleString()} / 2,000`}
function feedbackContextText(){const tool=state.tool?TOOLS[state.tool]?.name:null;return `${state.mode==='project'?project.name:'Portfolio / unassigned'} · ${tool||globalItems.find(x=>x.id===state.global)?.label||'Workspace'} · ${state.tool?TOOLS[state.tool].tabs[state.toolTab]?.label||'Overview':'Main view'}`}
function updateFeedbackContext(){const el=q('#feedbackContext');if(el)el.innerHTML=`<b>Captured context</b><br>${feedbackContextText()}`}
function submitFeedback(){const text=q('#feedbackText').value.trim();if(text.length<10){showToast('Please enter at least 10 characters.');return}feedbackRecords.unshift({title:text.slice(0,72)+(text.length>72?'…':''),status:'Received',date:'Just now',category:feedbackCategory,context:feedbackContextText()});q('#feedbackText').value='';updateFeedbackCount();showToast('Feedback submitted with workspace context.');toggleFeedback(false)}
function renderFeedbackRecords(){const el=q('#feedbackRecords');if(!el)return;el.innerHTML=feedbackRecords.map(r=>`<div class="feedback-record"><b>${r.title}</b><span>${r.category||'Feature request'} · ${r.status} · ${r.date}</span>${r.context?`<span>${r.context}</span>`:''}</div>`).join('')}
function showToast(message){const t=q('#feedbackToast');t.textContent=message;t.classList.add('show');clearTimeout(window.__feedbackToastTimer);window.__feedbackToastTimer=setTimeout(()=>t.classList.remove('show'),2400)}
function renderAll(){renderGlobalMenu();renderNavigator();renderMain();renderInspector();renderTopbar();updateFeedbackContext()}
initFeedback();
renderAll();
</script>
