.pm-shell{display:grid;gap:13px}.pm-toolbar{display:flex;align-items:center;gap:9px;padding:11px 13px;border:1px solid var(--border);background:#fff;border-radius:13px;box-shadow:var(--soft)}.pm-toolbar .spacer{flex:1}.pm-toolbar b{font-size:14px}.pm-toolbar span{font-size:12px;color:var(--muted)}.pm-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.pm-kpi{padding:15px;border:1px solid var(--border);border-radius:15px;background:#fff;box-shadow:var(--soft)}.pm-kpi label{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);font-weight:750}.pm-kpi strong{display:block;font-size:25px;margin-top:7px}.pm-kpi small{display:block;font-size:12px;color:var(--muted);margin-top:4px}.pm-grid{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(310px,.8fr);gap:13px}.pm-panel{background:#fff;border:1px solid var(--border);border-radius:16px;padding:16px;box-shadow:var(--soft);min-width:0}.pm-panel h2{font-size:18px;margin:0 0 4px}.pm-panel h3{font-size:15px;margin:0 0 9px}.pm-sub{font-size:12px;color:var(--muted);margin-bottom:12px}.pm-table{width:100%;border-collapse:collapse}.pm-table th{text-align:left;font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;padding:9px;border-bottom:1px solid var(--border)}.pm-table td{padding:9px;border-bottom:1px solid rgba(16,32,51,.06);font-size:13px}.pm-table input,.pm-table select{width:100%;min-width:80px;border:1px solid rgba(16,32,51,.13);border-radius:8px;padding:7px 8px;background:#fff;font-size:13px}.pm-progress{height:7px;background:#edf3f2;border-radius:99px;overflow:hidden}.pm-progress i{display:block;height:100%;background:linear-gradient(90deg,var(--teal),var(--jade));border-radius:99px}.gantt-row{display:grid;grid-template-columns:180px 1fr 55px;align-items:center;gap:9px;padding:9px 0;border-bottom:1px solid rgba(16,32,51,.06)}.gantt-row b{font-size:13px}.gantt-track{height:18px;border-radius:6px;background:#edf3f2;overflow:hidden}.gantt-bar{height:100%;border-radius:6px;background:linear-gradient(90deg,var(--cobalt),#73a3ff)}.gantt-row output{font-size:12px;color:var(--muted);text-align:right}.kanban{display:grid;grid-template-columns:repeat(4,minmax(185px,1fr));gap:10px;overflow:auto}.kanban-col{background:#f5f8f7;border:1px solid var(--border);border-radius:14px;padding:10px;min-height:280px}.kanban-head{display:flex;justify-content:space-between;font-size:13px;font-weight:800;margin-bottom:9px}.kanban-head span{font-size:11px;color:var(--muted);background:#fff;border-radius:99px;padding:3px 7px}.task-card{background:#fff;border:1px solid var(--border);border-radius:11px;padding:10px;margin-bottom:8px;cursor:pointer}.task-card:hover{border-color:rgba(25,183,176,.38)}.task-card b{font-size:13px;display:block}.task-card small{display:block;font-size:11px;color:var(--muted);margin-top:5px}.task-tags{display:flex;gap:4px;margin-top:7px}.task-tags span{font-size:10px;padding:3px 6px;border-radius:6px;background:var(--aqua);color:var(--deep)}.action-list{display:grid;gap:8px}.action-line{display:flex;align-items:center;gap:10px;padding:10px;border:1px solid var(--border);border-radius:11px;background:#fff}.action-line input{width:17px;height:17px;accent-color:var(--teal)}.action-line b{font-size:13px}.action-line small{display:block;font-size:11px;color:var(--muted);margin-top:2px}.action-line>span{margin-left:auto;font-size:11px;color:var(--muted)}.resource-row{display:grid;grid-template-columns:165px 100px 1fr 60px;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid rgba(16,32,51,.06)}.resource-row b{font-size:13px}.resource-row span{font-size:12px;color:var(--muted)}.resource-row input{accent-color:var(--teal)}.pm-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.pm-field{display:flex;flex-direction:column;gap:5px}.pm-field label{font-size:11px;color:var(--muted);font-weight:750;text-transform:uppercase;letter-spacing:.05em}.pm-field input{border:1px so