function roleLabel(){return (roles.find(x=>x[0]===state.role)||['','Architect'])[1]}function profile(){return rp[state.role]||rp.architect}function hints(){return roleMap[state.role]||roleMap.architect}function money(n){return 'R '+Math.round(Number(n)||0).toLocaleString('en-ZA')}
function banner(){const p=profile();return `<div class="role-banner"><div class="role-avatar">${p[0]}</div><div class="role-copy"><b>${roleLabel()} experience</b><span>${p[1]}. The datum and tool navigation adapt to this role.</span></div><div class="role-tags">${p[2].map(x=>`<span>${x}</span>`).join('')}</div></div>`}
window.setRole=function(v){state.role=v;state.toolTab=0;state.pmTab='dashboard';renderAll();showToast('Switched to '+roleLabel()+' experience.')};window.selectProjectStage=function(s){project.stage=s;state.tool=null;state.mode='project';state.global='projects';renderAll();showToast(s+' stage selected — datum tools updated.')};window.setDatumZoom=function(v){state.datumZoom=Math.max(.65,Math.min(1.35,Number(v)||1));const w=q('.datum-world');if(w)w.style.transform=`scale(${state.datumZoom})`;const r=q('#datumZoom');if(r)r.value=state.datumZoom;const o=q('#datumOut');if(o)o.value=Math.round(state.datumZoom*100)+'%'};window.stepDatumZoom=d=>setDatumZoom(state.datumZoom+d);window.fitDatum=()=>setDatumZoom(.86);
function stageIds(){const all=(stageMap[project.stage]||[]).filter(id=>TOOLS[id]);const rel=hints();return [...new Set([...all.filter(id=>rel.includes(id)),...all.filter(id=>['practice','forms','wingman','project_passport'].includes(id)),...all])].slice(0,10)}function metric(id){return ({practice:['Programme & resources','Margin 26%'],planning:['2 active applications','Next deadline 4 Aug'],municipal:['Readiness 82%','4 blockers'],xa:['7 / 9 components pass','Fenestration pending'],forms:['6 forms exported','2 signatures pending'],bom:['47 material lines','R1.86m estimate'],specforge:['64 sections','12 clauses flagged'],itp:['3 hold points','1 NCR linked'],safety:['Safety file 91%','0 incidents'],wingman:['Project context active','6 suggestions'],project_passport:['Health 78%','3 decisions due']}[id]||['Project-connected','Open workspace'])}
window.renderProjectSpace=function(){const ids=stageIds(),n1=Math.ceil(ids.length/2),cards=ids.map((id,i)=>{const top=i<n1,idx=top?i:i-n1,count=top?n1:ids.length-n1,left=count<2?45:9+idx*(82/(count-1));return [id,left+'%',top?'11%':'67%',top?'above':'below']});return `${pageHead(project.name,'A stage-driven project workflow navigation centre. Select a stage to reposition the relevant tools on the datum.','projects','core',`<button class="btn ghost" onclick="openTool('practice','project')">${icon('practice_management',16)} Plan project</button><button class="btn ghost" onclick="openTool('wingman','project')">${icon('wingman',16)} Ask Wingman</button><button class="btn" onclick="toggleFeedback(true)">${icon('feedback',16)} Give feedback</button>`)}${banner()}<section class="project-hero"><div class="project-top"><div><h2>${project.name}</h2><p>${project.location} · ${project.client} · ${project.professional}</p></div><span class="status green">● In progress · ${project.progress}%</span></div><div class="stages">${stages.map((s,i)=>`<button class="stage ${s===project.stage?'active':''}" onclick="selectProjectStage('${s}')" title="Show ${s} stage tools"><i>${i+1}</i><span>${s}</span></button>`).join('')}</div><div class="stage-help"><b>${project.stage} stage:</b> ${stageCopy[project.stage]}</div></section><section class="datum-viewport"><div class="datum-world" style="transform:scale(${state.datumZoom})"><div class="datum-line"></div><div class="datum-origin"><img src="${LOGO}" alt="Architex bird"></div><div class="datum-label">DATUM<span>single line of truth</span></div><div class="datum-stage-badge"><b>${project.stage} tools for ${roleLabel()}</b>${ids.length} role-relevant project workspaces are active at this point in the project.</div>${cards.map(c=>`<i class="datum-node" style="left:${c[1]}"></i>`).join('')}${cards.map(c=>datumV6(...c)).join('')}</div><div class="datum-controls"><button onclick="stepDatumZoom(-.1)" title="Zoom out">−</button><input id="datumZoom" type="range" min=".65" max="1.35" step=".05" value="${state.datumZoom}" oninput="setDatumZoom(this.value)"><output id="datumOut">${Math.round(state.datumZoom*100)}%</output><button onclick="stepDatumZoom(.1)" title="Zoom in">+</button><button onclick="fitDatum()" title="Fit datum to view">${icon('expand',17)}</button></div></section>`};
function datumV6(id,left,top,side){const t=TOOLS[id],m=metric(id);return `<article class="datum-card ${side}" style="left:${left};top:${top};${toneStyle(t.tone)}" onclick="openTool('${id}','project')" title="Open ${t.name}"><div class="dc-head"><div class="dc-icon">${icon(t.icon,23)}</div><strong>${t.name}</strong></div><p>${t.summary}</p><div class="mini-row"><span>${m[0]}</span><span>›</span></div><div class="mini-row"><span>${m[1]}</span><span class="status ${/pending|block|flag|due/i.test(m[1])?'amber':'green'}">${t.status==='live'?'Live':'Scaffold'}</span></div></article>`}
function pmAllowed(k){if(['architect','bep','cpm','developer','firm_admin','admin','platform_admin'].includes(state.role))return true;const x={client:['dashboard','actions','notifications','programme','milestones','calendar','risks','budget','valuations','drawings','documents'],engineer:['dashboard','actions','programme','tasks','milestones','calendar','team','rfis','risks','quality','timesheets','drawings','documents','agents'],quantity_surveyor:['dashboard','actions','programme','tasks','milestones','fees','timesheets','profitability','forecast','budget','valuations','procurement','contracts','documents','agents'],contractor:['dashboard','actions','programme','tasks','milestones','calendar','team','site_diary','rfis','risks','quality','budget','valuations','procurement','contracts','drawings','documents','agents'],site_manager:['dashboard','actions','programme','tasks','milestones','calendar','team','site_diary','rfis','risks','quality','documents','agents'],health_safety:['dashboard','actions','programme','tasks','milestones','calendar','team','site_diary','risks','documents','agents'],supplier:['dashboard','actions','notifications','procurement','contracts','documents'],freelancer:['dashboard','actions','tasks','calendar','timesheets','documents']}[state.role]||['dashboard','actions','tasks','documents'];return x.includes(k)}
function pmNav(){const nav=q('#navigator'),groups={};TOOLS.practice.tabs.filter(x=>pmAllowed(x.key)).forEach(x=>(groups[x.group]??=[]).push(x));nav.innerHTML=`<div class="nav-head"><div class="nav-compact-mark" title="Practice & Project Management">${icon('practice_management',27)}</div><div class="kicker">${state.mode==='project'?'Project-connected tool':'Standalone practice tool'}</div><div class="nav-title">Practice & Project Management</div><div class="nav-sub">${state.mode==='project'?project.name+' · '+project.stage+' stage':'Portfolio, projects, people and performance'}</div>${modeSwitch()}</div><div class="back-row" onclick="${state.mode==='project'?'openProjectSpace()':'openStandalone()'}">${icon('projects',18)}<span class="nav-label">${state.mode==='project'?'Back to datum project space':'Back to standalone library'}</span></div><div class="nav-note"><b>${roleLabel()} view</b><br>${profile()[1]}</div>${Object.entries(groups).map(([g,a])=>`<div class="nav-section"><div class="nav-heading">${g}</div>${a.map(t=>{const i=TOOLS.practice.tabs.indexOf(t);return `<button class="nav-row ${state.pmTab===t.key?'active':''}" style="${toneStyle('cobalt')}" onclick="setToolTab(${i})" title="${t.label}"><span class="nav-icon">${icon(iconForTab(t,t.icon),21)}</span><span class="nav-label">${t.label}</span></button>`}).join('')}</div>`).join('')}<div class="nav-note"><b>Full project planning:</b><br>Programme, tasks, milestones, resources, fees, time, forecasting and profitability share one data model.</div>`}
function kpis(){const f=data.fee,fee=f.construction*f.percent/100,cost=data.times.reduce((s,x)=>s+x[3],0)+f.expenses,margin=Math.round((f.invoiced-cost)/f.invoiced*100);return `<div class="pm-kpis"><article class="pm-kpi"><label>Overall progress</label><strong>${project.progress}%</strong><small>${project.stage} stage</small></article><article class="pm-kpi"><label>Planned fee</label><strong>${money(fee)}</strong><small>${f.percent}% of construction cost</small></article><article class="pm-kpi"><label>Open actions</label><strong>${data.tasks.filter(x=>x[1]!=='Done').length}</strong><small>${data.tasks.filter(x=>x[4]==='Critical'&&x[1]!=='Done').length} critical</small></article><article class="pm-kpi"><label>Current margin</label><strong>${margin}%</strong><small>${money(f.invoiced-cost)} contribution</small></article></div>`}
function dashboard(){return `${kpis()}<div class="pm-grid"><section class="pm-panel"><h2>Project delivery pulse</h2><div class="pm-sub">Programme and current progress.</div>${data.programme.slice(0,6).map(x=>`<div class="gantt-row"><b>${x[0]}</b><div class="gantt-track"><div class="gantt-bar" style="width:${x[2]}%"></div></div><output>${x[2]}%</output></div>`).join('')}</section><section class="pm-panel"><h2>Priority actions</h2><div class="pm-sub">Role-routed work requiring attention.</div><div class="action-list">${data.tasks.filter(x=>x[1]!=='Done').map((x,i)=>`<div class="action-line"><input type="checkbox" onchange="completeTask(${data.tasks.indexOf(x)},this.checked)"><div><b>${x[0]}</b><small>${x[2]} · ${x[3]}</small></div><span>${x[4]}</span></div>`).join('')}</div></section><section class="pm-panel"><h2>Resource capacity</h2>${data.resources.slice(0,4).map(x=>`<div class="resource-row"><b>${x[0]}</b><span>${x[1]}</span><div class="pm-progress"><i style="width:${x[2]}%"></i></div><span>${x[2]}%</span></div>`).join('')}</section><section class="pm-panel"><h2>Commercial outlook</h2><div class="bar-chart">${[54,66,61,72,79,85].map((v,i)=>`<i style="height:${v}%"><span>${['Feb','Mar','Apr','May','Jun','Jul'][i]}</span></i>`).join('')}</div></section></div>`}
function programme(){return `<section class="pm-panel"><h2>Full project programme</h2><div class="pm-sub">Edit workstreams, owners, durations and progress.</div><table class="pm-table"><thead><tr><th>Workstream</th><th>Owner</th><th>Weeks</th><th>Progress</th><th>Programme</th></tr></thead><tbody>${data.programme.map((x,i)=>`<tr><td><input value="${x[0]}" onchange="updateProgramme(${i},0,this.value)"></td><td><input value="${x[3]}" onchange="updateProgramme(${i},3,this.value)"></td><td><input type="number" value="${x[1]}" onchange="updateProgramme(${i},1,this.value)"></td><td><input type="range" min="0" max="100" value="${x[2]}" oninput="updateProgramme(${i},2,this.value)"></td><td><div class="gantt-track"><div class="gantt-bar" style="width:${Math.max(7,x[2])}%"></div></div></td></tr>`).join('')}</tbody></table><div style="margin-top:12px"><button class="btn" onclick="addProgramme()">Add workstream</button></div></section>`}
function tasks(){const s=['To do','In progress','Review','Done'];return `<section class="pm-panel"><div style="display:flex;align-items:center"><div><h2>Tasks board</h2><div class="pm-sub">Click a task to move it through the workflow.</div></div><button class="btn" style="margin-left:auto" onclick="addTask()">Add task</button></div><div class="kanban">${s.map(st=>{const a=data.tasks.filter(x=>x[1]===st);return `<div class="kanban-col"><div class="kanban-head">${st}<span>${a.length}</span></div>${a.map(x=>{const i=data.tasks.indexOf(x);return `<article class="task-card" onclick="cycleTask(${i})"><b>${x[0]}</b><small>${x[2]} · ${x[3]}</small><div class="task-tags"><span>${x[4]}</span><span>${x[1]}</span></div></article>`}).join('')}</div>`}).join('')}</div></section>`}
function milestones(){return `<section class="pm-panel"><div style="display:flex"><div><h2>Milestone plan</h2><div class="pm-sub">Stage gates and delivery dates.</div></div><button class="btn" style="margin-left:auto" onclick="addMilestone()">Add milestone</button></div><div class="action-list">${data.milestones.map((x,i)=>`<div class="action-line"><input type="checkbox" ${x[2]?'checked':''} onchange="toggleMilestone(${i},this.checked)"><div><b>${x[0]}</b><small>${x[1]}</small></div><span>${x[2]?'Complete':'Planned'}</span></div>`).join('')}</div></section>`}
function calendar(){const e={3:'Design review',7:'QS cost check',11:'Municipal pack',15:'Client approval',19:'Tender issue',24:'Team workshop',28:'Invoice due'};return `<section class="pm-panel"><h2>August 2026 project calendar</h2><div class="pm-sub">Milestones, reviews, approvals and commercial events.</div><div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<b style="font-size:11px;color:var(--muted);padding:4px">${x}</b>`).join('')}${Array.from({length:35},(_,i)=>{const d=i-4;return `<div class="cal-day"><b>${d>0&&d<32?d:''}</b>${e[d]?`<div class="cal-event">${e[d]}</div>`:''}</div>`}).join('')}</div></section>`}
function team(){return `<section class="pm-panel"><h2>Team and resource planning</h2><div class="pm-sub">Adjust allocations to balance demand and capacity.</div>${data.resources.map((x,i)=>`<div class="resource-row"><b>${x[0]}</b><span>${x[1]}</span><input type="range" min="0" max="130" value="${x[2]}" oninput="updateResource(${i},this.value,this)"><span><output>${x[2]}%</output></span></div>`).join('')}</section>`}
function fees(){const f=data.fee,fee=f.construction*f.percent/100,margin=Math.round((fee-f.planned)/fee*100);return `<section class="pm-panel"><h2>Fee planning</h2><div class="pm-sub">Model the fee, delivery cost and planned margin.</div><div class="pm-fields"><div class="pm-field"><label>Construction cost</label><input type="number" value="${f.construction}" onchange="updateFee('construction',this.value)"></div><div class="pm-field"><label>Fee percentage</label><input type="number" step=".1" value="${f.percent}" onchange="updateFee('percent',this.value)"></div><div class="pm-field"><label>Planned delivery cost</label><input type="number" value="${f.planned}" onchange="updateFee('planned',this.value)"></div></div><div class="pm-kpis" style="margin-top:13px"><article class="pm-kpi"><label>Calculated fee</label><strong>${money(fee)}</strong><small>Before VAT</small></article><article class="pm-kpi"><label>Planned margin</label><strong>${margin}%</strong><small>${money(fee-f.planned)}</small></article><article class="pm-kpi"><label>Invoiced</label><strong>${money(f.invoiced)}</strong><small>${Math.round(f.invoiced/fee*100)}% billed</small></article><article class="pm-kpi"><label>Expenses</label><strong>${money(f.expenses)}</strong><small>Current project</small></article></div></section>`}
function times(){const h=data.times.reduce((s,x)=>s+x[1],0),c=data.times.reduce((s,x)=>s+x[3],0);return `<section class="pm-panel"><div style="display:flex"><div><h2>Timesheets and expenses</h2><div class="pm-sub">Record time against project stages.</div></div><button class="btn" style="margin-left:auto" onclick="addTime()">Add time</button></div><table class="pm-table"><thead><tr><th>Person</th><th>Stage</th><th>Hours</th><th>Cost</th></tr></thead><tbody>${data.times.map(x=>`<tr><td>${x[0]}</td><td>${x[2]}</td><td>${x[1]}</td><td>${money(x[3])}</td></tr>`).join('')}</tbody></table><div class="pm-kpis" style="margin-top:13px"><article class="pm-kpi"><label>Total hours</label><strong>${h}</strong><small>Current period</small></article><article class="pm-kpi"><label>Labour cost</label><strong>${money(c)}</strong><small>Approved time</small></article></div></section>`}
function profitability(){const f=data.fee,fee=f.construction*f.percent/100,cost=data.times.reduce((s,x)=>s+x[3],0)+f.expenses,con=f.invoiced-cost,mar=Math.round(con/f.invoiced*100);return `<section class="pm-panel"><h2>Project profitability</h2><div class="pm-sub">Income, delivery cost and cost-to-complete.</div><div class="pm-kpis"><article class="pm-kpi"><label>Agreed fee</label><strong>${money(fee)}</strong><small>Current appointment</small></article><article class="pm-kpi"><label>Invoiced</label><strong>${money(f.invoiced)}</strong><small>${Math.round(f.invoiced/fee*100)}% billed</small></article><article class="pm-kpi"><label>Delivery cost</label><strong>${money(cost)}</strong><small>Time plus expenses</small></article><article class="pm-kpi"><label>Contribution margin</label><strong>${mar}%</strong><small>${money(con)}</small></article></div><div class="bar-chart" style="margin-top:14px">${[38,41,44,43,47,49,52,55].map((v,i)=>`<i style="height:${v+25}%"><span>W${i+1}</span></i>`).join('')}</div></section>`}
function forecast(){return `<section class="pm-panel"><h2>Income and resource forecast</h2><div class="pm-sub">Weighted workload and revenue outlook.</div><div class="bar-chart" style="height:280px">${[62,68,74,81,76,88,94,91,97,82,76,70].map((v,i)=>`<i style="height:${v}%"><span>${['Aug','Sep','Oct','Nov','Dec','Jan','Feb','Mar','Apr','May','Jun','Jul'][i]}</span></i>`).join('')}</div></section>`}
function generic(k){const m={actions:['Action Centre','Role-routed work requiring attention.'],notifications:['Notifications','Updates, approvals and system alerts.'],site_diary:['Site Diary','Daily site records, labour, weather and progress evidence.'],rfis:['RFIs & Instructions','Questions, responses, decisions and formal instructions.'],risks:['Issues & Risks','Risk owners, probability, impact and mitigation.'],quality:['Quality & Snags','Inspections, snags, NCRs and close-out evidence.'],budget:['Budget & Cost','Commitments, actuals and cost-to-complete.'],valuations:['Valuations','Progress valuation, retention and payment status.'],procurement:['Procurement','RFQs, comparisons, recommendations and awards.'],contracts:['Contracts','Appointments, building contracts and variations.'],drawings:['Drawings','Current set, revisions and coordination status.'],documents:['Documents','Controlled project files and correspondence.'],agents:['AI Agents','Project-aware programme, commercial and compliance agents.']}[k]||['Workspace','Project-management workspace.'];return `<section class="pm-panel"><h2>${m[0]}</h2><div class="pm-sub">${m[1]}</div><div class="action-list">${['Current project record','Workflow action','Audit and approval event'].map((x,i)=>`<div class="action-line"><div class="dc-icon">${icon(iconForTab({label:m[0]},'practice_management'),19)}</div><div><b>${x}</b><small>${['Updated today','Due this week','Awaiting review'][i]}</small></div><span>${['Open','Review','Current'][i]}</span></div>`).join('')}</div></section>`}
window.renderPractice=function(){const k=state.pmTab,t=pmTabs.find(x=>x[0]===k)?.[1]||'Dashboard';let body=k==='dashboard'?dashboard():k==='programme'?programme():k==='tasks'?tasks():k==='milestones'?milestones():k==='calendar'?calendar():k==='team'?team():k==='fees'?fees():k==='timesheets'?times():k==='profitability'?profitability():k==='forecast'?forecast():generic(k);return `${pageHead('Practice & Project Management — '+t,'Plan and control the complete project while connecting practice resources, fees, time, forecasts and profitability.','practice_management','cobalt',`<button class="btn ghost" onclick="showToast('Practice report exported.')">${icon('export',16)} Export</button><button class="btn" onclick="toggleFeedback(true)">${icon('feedback',16)} Give feedback</button>`)}${banner()}<div class="pm-shell"><div class="pm-toolbar"><b>${state.mode==='project'?project.name:'Practice portfolio'}</b><span>${state.mode==='project'?project.stage+' stage · '+project.progress+'% complete':'All projects and live performance'}</span><span class="spacer"></span><span>Viewing as <b>${roleLabel()}</b></span></div>${body}<div class="pm-note">Functional prototype: programme, tasks, resources, fees, time, forecasting and profitability operate inside the Datum OS shell.</div></div>`};
window.completeTask=(i,v)=>{data.tasks[i][1]=v?'Done':'To do';renderMain();renderNavigator()};window.cycleTask=i=>{const s=['To do','In progress','Review','Done'];data.tasks[i][1]=s[(s.indexOf(data.tasks[i][1])+1)%4];renderMain()};window.addTask=()=>{const n=prompt('Task name','New project task');if(n){data.tasks.push([n,'To do',roleLabel(),'This week','Medium']);renderMain()}};window.addMilestone=()=>{const n=prompt('Milestone name','New milestone');if(n){data.milestones.push([n,'30 Sep 2026',false]);renderMain()}};window.toggleMilestone=(i,v)=>{data.milestones[i][2]=v;renderMain()};window.addProgramme=()=>{data.programme.push(['New workstream',4,0,roleLabel()]);renderMain()};window.updateProgramme=(i,k,v)=>{data.programme[i][k]=[1,2].includes(k)?Number(v):v;if(k!==2)renderMain()};window.updateResource=(i,v,e)=>{data.resources[i][2]=Number(v);e.parentElement.querySelector('output').textContent=v+'%'};window.updateFee=(k,v)=>{data.fee[k]=Number(v);renderMain()};window.addTime=()=>{const h=Number(prompt('Hours worked','7.5'));if(h){data.times.push([roleLabel(),h,project.stage,h*650]);renderMain()}};
function installRole(){const top=q('.topbar');if(!top)return;let h=q('#roleSwitch');if(!h){h=document.createElement('div');h.id='roleSwitch';h.className='role-switch';top.insertBefore(h,q('#wingmanTop'))}h.innerHTML=`<label>Viewing as</label><select onchange="setRole(this.value)">${roles.map(x=>`<option value="${x[0]}" ${x[0]===state.role?'selected':''}>${x[1]}</option>`).join('')}</select>`;const u=q('.rail-user .user-copy');if(u)u.innerHTML=`<b>${roleLabel()}</b><span>${profile()[1]}</span>`;const a=q('.rail-user .avatar');if(a)a.textContent=profile()[0]}
function tips(){qa('.os-item,.nav-row,.top-btn').forEach(e=>{const x=e.title||e.getAttribute('aria-label')||e.querySelector('.nav-label,.os-label')?.textContent?.trim();if(x)e.dataset.tip=x})}
window.toolGroups=function(mode){const g={};Object.entries(TOOLS).forEach(([id,t])=>{if(mode==='project'&&!hints().includes(id)&&!['practice','forms','wingman','feedback','project_passport'].includes(id))return;(g[t.group]??=[]).push([id,t])});return Object.entries(g).map(([n,a])=>`<div class="nav-section"><div class="nav-heading">${n}</div>${a.map(([id,t])=>`<button class="nav-row" style="${toneStyle(t.tone)}" onclick="openTool('${id}','${mode}')" title="${t.name}"><span class="nav-icon">${icon(t.icon,21)}</span><span class="nav-label">${t.name}</span>${t.status==='scaffold'?'<span class="badge">Scaffold</span>':''}</button>`).join('')}</div>`).join('')};
window.renderNavigator=function(){if(state.tool==='practice'){pmNav();tips();return}old.renderNavigator();if(!state.tool&&state.mode==='project'){const h=q('#navigator .nav-head');if(h&&!q('#navigator .role-card'))h.insertAdjacentHTML('afterend',`<div class="nav-note role-card"><b>${roleLabel()} view</b><br>${profile()[1]}</div>`);const b=[...qa('#navigator .nav-row')].find(x=>x.onclick?.toString().includes("'practice'"));if(b){const l=b.querySelector('.nav-label');if(l)l.textContent='Practice & Project Management'}}tips()};
window.setToolTab=function(i){if(state.tool==='practice'){state.toolTab=i;state.pmTab=TOOLS.practice.tabs[i]?.key||'dashboard';renderNavigator();renderMain();renderInspector();updateFeedbackContext();return}old.setToolTab(i)};
window.renderMain=function(){if(state.tool==='practice'){q('#main').innerHTML=renderPractice();return}old.renderMain()};window.renderTopbar=function(){old.renderTopbar();installRole();tips()};window.renderInspector=function(){old.renderInspector();if(!state.tool&&state.mode==='project')q('#inspectBody')?.insertAdjacentHTML('afterbegin',`<div class="inspect-note"><b>${roleLabel()} experience</b><br>${profile()[1]}. Select a work stage to update the datum.</div>`)};window.renderAll=function(){old.renderAll();installRole();tips()};renderAll();
})();
</script>


<style id="architex-v7-meetings-style">
/* V7 — Architex Meetings integrated into Datum OS */
.mtg-shell{display:grid;gap:14px}
.mtg-context-ribbon{display:flex;align-items:center;gap:10px;padding:11px 13px;border:1px solid var(--border);border-radius:13px;background:#fff;box-shadow:var(--soft)}
.mtg-context-ribbon b{font-size:14px}.mtg-context-ribbon span{font-size:12px;color:var(--muted)}.mtg-context-ribbon .spacer{flex:1}
.mtg-orientation{padding:5px 8px;border-radius:99px;background:var(--aqua);color:var(--deep)!important;font-weight:750}
