.mtg-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.mtg-field{display:flex;flex-direction:column;gap:5px}.mtg-field.full{grid-column:1/-1}.mtg-field label{font-size:11px;text-transform:uppercase;letter-spacing:.05em;font-weight:750;color:var(--muted)}.mtg-field input,.mtg-field select,.mtg-field textarea{border:1px solid rgba(16,32,51,.14);border-radius:9px;padding:10px;font-size:14px;background:#fff;color:var(--ink)}.mtg-field textarea{min-height:100px;resize:vertical}
