.mtg-room-panel{background:#0e2233;border:1px solid #244154;border-radius:13px;min-height:0;display:grid;grid-template-rows:auto minmax(0,1fr)}.mtg-room-tabs{display:grid;grid-template-columns:repeat(4,1fr);gap:3px;padding:7px;border-bottom:1px solid #244154}.mtg-room-tabs button{border:0;background:transparent;color:#a9bfd0;padding:8px 3px;border-radius:7px;font-size:10px;cursor:pointer}.mtg-room-tabs button.active{background:#18364a;color:#fff}.mtg-room-panel-body{overflow:auto;padding:11px}.mtg-room-panel-body h3{font-size:14px;margin:0 0 9px}.mtg-room-panel-body p,.mtg-room-panel-body li{font-size:11px;line-height:1.5;color:#b8c9d6}.mtg-note{padding:9px;border-left:3px solid var(--teal);background:#122d40;border-radius:0 8px 8px 0;margin-bottom:8px;font-size:11px;line-height:1.45}.mtg-chat{padding:9px;border-radius:9px;background:#122d40;margin-bottom:7px}.mtg-chat b{font-size:11px}.mtg-chat p{margin:3px 0 0}
.mtg-controls{display:flex;justify-content:center;align-items:center;gap:8px;padding-top:11px}.mtg-control{width:46px;height:46px;border:0;border-radius:50%;display:grid;place-items:center;background:#1d3648;color:#fff;cursor:pointer}.mtg-control:hover{background:#294c63}.mtg-control.off{background:#5a2630}.mtg-control.leave{width:108px;border-radius:24px;background:#b63838;font-size:12px;font-weight:800}.mtg-control .ax-icon .outline{fill:transparent;stroke:#fff}.mtg-control .ax-icon .line{stroke:#fff}.mtg-control .ax-icon .fold{fill:#BFE9E2;stroke:#fff}
