.mtg-segment{padding:11px;border-bottom:1px solid var(--border);font-size:12px;line-height:1.5;cursor:pointer}.mtg-segment:hover,.mtg-segment.active{background:var(--aqua)}.mtg-segment b{color:var(--deep)}.mtg-segment small{display:block;color:var(--muted);margin-bottom:4px}
.mtg-minute{padding:11px;border:1px solid var(--border);border-radius:11px;margin-bottom:8px;cursor:pointer}.mtg-minute.active{border-color:var(--teal);background:var(--aqua)}.mtg-minute label{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:var(--lavender);font-weight:850}.mtg-minute textarea{width:100%;min-height:72px;border:0;background:transparent;resize:vertical;font:inherit;color:var(--ink);padding:5px 0}.mtg-source{font-size:10px;color:var(--muted)}
.mtg-outcome{padding:11px;border:1px solid var(--border);border-radius:11px;margin-bottom:8px}.mtg-outcome-head{display:flex;align-items:center;gap:7px}.mtg-outcome-head b{font-size:13px}.mtg-outcome p{font-size:11px;color:var(--muted);line-height:1.45}.mtg-outcome-actions{display:flex;gap:6px}.mtg-outcome-actions button{min-height:34px;border:1px solid var(--border);background:#fff;border-radius:8px;padding:6px 9px;font-size:11px;cursor:pointer}.mtg-outcome-actions button.accepted{border-color:var(--teal);background:var(--aqua);color:var(--deep);font-weight:800}.mtg-outcome-actions button.rejected{border-color:#e7a1a1;background:#fff0f0;color:#9d3434;font-weight:800}
.mtg-issued{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:14px}.mtg-document{background:#fff;border:1px solid var(--border);border-radius:16px;padding:25px;box-shadow:var(--soft)}.mtg-document h1{font-size:24px;margin:0}.mtg-document h2{font-size:17px;margin-top:23px}.mtg-document p,.mtg-document li{font-size:13px;line-height:1.65;color:#3f4d60}.mtg-signoff{padding-top:18px;margin-top:25px;border-top:1px solid var(--border);display:grid;grid-template-columns:1fr 1fr;gap:20px}.mtg-issued-side{display:grid;gap:10px;height:max-content}.mtg-side-card{padding:14px;background:#fff;border:1px solid var(--border);border-radius:13px}.mtg-side-card h3{font-size:14px;margin:0 0 7px}.mtg-side-card p,.mtg-side-card li{font-size:11px;color:var(--muted);line-height:1.5}
