.collab-hub{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.collab-card{padding:17px;border:1px solid var(--border);border-radius:16px;background:#fff;box-shadow:var(--soft);cursor:pointer}.collab-card:hover{transform:translateY(-2px);border-color:rgba(25,183,176,.38)}.collab-card h3{font-size:16px;margin:8px 0 4px}.collab-card p{font-size:12px;color:var(--muted);line-height:1.5}
