    .field label{color:#657287!important;font-size:12px!important}.field input,.field select{background:#fff!important;color:#102033!important;border:1px solid rgba(16,32,51,.14)!important;border-radius:9px!important;padding:9px 10px!important;font-size:14px!important}.field select option{background:#fff!important;color:#102033!important}.field input:focus,.field select:focus{border-color:#19B7B0!important;box-shadow:0 0 0 3px rgba(25,183,176,.09)!important}
    .calc-btn{background:#167E79!important;color:#fff!important;border-radius:9px!important;font-size:13px!important;padding:10px!important}.calc-btn:hover{background:#116d68!important;opacity:1!important}
    .result-row{border-bottom:1px solid rgba(16,32,51,.06)!important}.rk{color:#657287!important;font-size:12px!important}.rv{color:#102033!important;font-size:13px!important}.badge.pass{background:rgba(40,168,107,.10)!important;color:#218956!important}.badge.fail{background:rgba(217,87,71,.10)!important;color:#b34b3e!important}.badge.warn{background:rgba(255,176,32,.12)!important;color:#986500!important}
    .deriv{background:#f4f8f7!important;border-left-color:#19B7B0!important;color:#167E79!important;font-size:11.5px!important}.ref-table,.comparator-table{color:#102033!important}.ref-table th,.comparator-table th{color:#657287!important;border-bottom-color:rgba(16,32,51,.10)!important}.ref-table td,.comparator-table td{border-bottom-color:rgba(16,32,51,.06)!important}.ref-table tr:hover td{background:#f5faf9!important}
    .disclaimer{background:rgba(255,176,32,.10)!important;border-color:rgba(255,176,32,.27)!important;color:#805800!important;font-size:12px!important;line-height:1.55!important}
    .util-bar{background:#edf3f2!important}.ax-native-context{margin:0 0 14px!important}
    @media(max-width:850px){.calc-grid{grid-template-columns:1fr!important}}
  `;

  function engineeringGroups(){const g={};TOOLS.engineering_calc.tabs.forEach((x,i)=>(g[x.group]??=[]).push([x,i]));return g}
  function engineeringNavigator(){
    const nav=q('#navigator'),t=TOOLS.engineering_calc,back=state.mode==='project'?"openProjectSpace()":"openStandalone()";
    nav.innerHTML=`<div class="nav-head"><div class="nav-compact-mark" title="Engineer's Calculation Hub">${icon('engineering_hub',27)}</div><div class="kicker">${state.mode==='project'?'Project engineering tool':'Standalone engineering tool'}</div><div class="nav-title">Engineer's Calculation Hub</div><div class="nav-sub">${state.mode==='project'?project.name+' · '+project.stage+' stage':'Multi-discipline calculation workspace'}</div>${modeSwitch()}</div><div class="back-row" onclick="${back}" title="${state.mode==='project'?'Back to datum project space':'Back to workspace tools'}">${icon(state.mode==='project'?'projects':'tools',18)}<span class="nav-label">${state.mode==='project'?'Back to datum project space':'Workspace tools'}</span></div><div class="eng-nav-note"><b>Professional workflow</b><br>Calculations are working evidence. Project issue, approval, certification and professional sign-off remain governed by their destination workflows.</div>${Object.entries(engineeringGroups()).map(([g,a])=>`<div class="nav-section"><div class="nav-heading">${g}</div>${a.map(([x,i])=>`<button class="nav-row ${state.toolTab===i?'active':''}" style="${toneStyle('cobalt')}" onclick="setEngineeringTab(${i})" title="${x.label}"><span class="nav-icon">${icon(x.icon,21)}</span><span class="nav-label">${x.label}</span></button>`).join('')}</div>`).join('')}<div class="nav-note"><b>Source preserved:</b><br>Every original input, result panel, derivation and calculator function remains active inside the central workspace.</div>`;
  }
  window.setEngineeringTab=function(i){state.toolTab=i;state.engineeringTab=i;renderNavigator();invokeToolAction(TOOLS.engineering_calc.tabs[i]);renderInspector();updateFeedbackContext()};
  function engineeringWorkflow(){return `<div class="eng-workflow"><b>Engineering workflow</b><span class="eng-step"><i>${icon('project_passport',15)}</i>Project context</span><span class="eng-arrow">→</span><span class="eng-step"><i>${icon('engineering_hub',15)}</i>Calculation</span><span class="eng-arrow">→</span><span class="eng-step"><i>${icon('document',15)}</i>Calculation record</span><span class="eng-arrow">→</span><span class="eng-step"><i>${icon('drawing',15)}</i>Drawing / RFI / Meeting</span><span class="eng-arrow">→</span><span class="eng-step"><i>${icon('workflow',15)}</i>Professional review</span><span class="eng-context">${state.mode==='project'?project.name+' · '+project.stage:'Unassigned / portfolio'}</span></div>`}
  function renderEngineering(){
    const t=TOOLS.engineering_calc;
    const actions=`<div class="engineering-actions">${state.mode==='standalone'?`<button class="btn ghost" onclick="attachProject()">${icon('attach',16)} Attach project</button>`:''}<button class="btn ghost" onclick="saveEngineeringCalculation(false)">${icon('document',16)} Save calculation</button><button class="btn" onclick="saveEngineeringCalculation(true)">${icon('workflow',16)} Send to review</button></div>`;
    return `${pageHead(t.name,t.summary,t.icon,t.tone,actions)}${godBanner()}${engineeringWorkflow()}<div class="tool-banner"><b>${state.mode==='project'?'Project-connected':'Standalone'} engineering workspace</b><span>·</span><span>${state.mode==='project'?`Inputs and saved outputs can reference ${project.name}, linked drawings and project records.`:'Calculations can remain unassigned or be attached to a project later.'}</span><span class="spacer"></span><span>Original calculation logic preserved · professional verification required</span></div><div class="tool-shell loading" id="toolShell"><iframe class="tool-frame" id="toolFrame" title="Engineer's Calculation Hub functional sample"></iframe></div>`;
  }
  window.saveEngineeringCalculation=function(review){state.engineeringSaved=true;showToast(review?'Calculation record sent to professional review.':'Calculation saved as a controlled working record.');renderInspector()};

  function godBanner(){if(!state.godMode)return'';return `<div class="god-banner"><div class="god-mark">${icon('god_mode',24)}</div><div><b>God Mode · Ecosystem Explorer</b><p>All Architex workspaces are visible for demonstration, learning and cross-discipline understanding. In production this is an exploration/sandbox layer: it does not grant contractual authority, professional sign-off or access to another party’s protected project data.</p></div><div class="god-actions"><span class="god-chip">All tools visible</span><span class="god-chip">Demo lens: ${roleLabel()}</span></div></div>`}

  function v8RoleIds(){const base=(V8_STAGE_MAP[project.stage]||[]).filter(id=>TOOLS[id]);if(state.godMode)return base.slice(0,12);const allowed=V8_ROLE_ACCESS[state.role]||V8_ROLE_ACCESS.architect;const common=['meetings','wingman','project_passport','forms'];const list=[...base.filter(id=>allowed.includes(id)),...base.filter(id=>common.includes(id))];return [...new Set(list)].filter(id=>TOOLS[id]).slice(0,10)}
  function v8Metric(id){if(id==='engineering_calc'){const map={Design:['Multi-discipline design checks','17 calculator workspaces'],Comply:['SANS-referenced evidence','Professional review required'],Build:['Site engineering checks','Link results to RFI / ITP']};return map[project.stage]||['Engineering calculations','Controlled working record']}if(id==='meetings'){const m={Brief:['Client brief workshop','Agenda draft'],Appoint:['Team appointment meeting','2 acceptances pending'],Design:['Design coordination','Live in 12 min'],Comply:['Compliance review','AI draft · Review required'],Procure:['Tender clarification','Equal issue record'],Build:['Site progress meeting','8 open actions'],Pay:['Commercial review','3 valuation actions'],'Close-out':['Handover review','Issued minutes · Rev 01']};return m[project.stage]||['Project meeting','Scheduled']}const k={practice:['Programme & resources','Project margin 26%'],planning:['2 active applications','Next deadline 4 Aug'],municipal:['Readiness 82%','4 blockers'],xa:['7 / 9 components pass','Fenestration pending'],forms:['6 forms exported','2 signatures pending'],bom:['47 material lines','R1.86m estimate'],specforge:['64 sections','12 clauses flagged'],itp:['3 hold points','1 NCR linked'],safety:['Safety file 91%','0 incidents'],wingman:['Project context active','6 suggestions'],project_passport:['Health 78%','3 decisions due']};return k[id]||[TOOLS[id]?.status==='live'?'Functional workspace':'Integration scaffold',TOOLS[id]?.stage||'Project-connected']}
  function v8DatumCard(id,left,top,side){const t=TOOLS[id],m=v8Metric(id);if(!t)return'';return `<article class="datum-card ${side} ${id==='engineering_calc'?'engineering-card':''} ${id==='meetings'?'meeting-datum-card':''}" style="left:${left};top:${top};${toneStyle(t.tone)}" onclick="openTool('${id}','project')" title="Open ${t.name}"><div class="dc-head"><div class="dc-icon">${icon(t.icon,23)}</div><strong>${t.name}</strong></div><p>${t.summary}</p><div class="mini-row"><span>${m[0]}</span><span>›</span></div><div class="mini-row"><span>${m[1]}</span><span class="status ${/pending|block|review|required|draft|action/i.test(m[1])?'amber':'green'}">${t.status==='live'?'Live':'Scaffold'}</span></div></article>`}
  window.renderProjectSpace=function(){
    const stages=['Brief','Appoint','Design','Comply','Procure','Build','Pay','Close-out'],ids=v8RoleIds(),n1=Math.ceil(ids.length/2),wide=state.godMode?1450:1120;
    const cards=ids.map((id,i)=>{const above=i<n1,idx=above?i:i-n1,count=above?n1:ids.length-n1,left=count<2?45:7+idx*(86/(count-1));return[id,left+'%',above?'11%':'67%',above?'above':'below']});
    return `${pageHead(project.name,state.godMode?'God Mode shows every stage-relevant workspace so users can understand the whole ecosystem and handoffs.':'A stage-driven project workflow navigation centre. The datum prioritises the workspaces relevant to this user and project stage.','projects','core',`<button class="btn ghost" onclick="openTool('practice','project')">${icon('practice_management',16)} Plan project</button><button class="btn ghost" onclick="openTool('engineering_calc','project')">${icon('engineering_hub',16)} Engineering</button><button class="btn ghost" onclick="openMeetings('project')">${icon('meetings',16)} Meetings</button><button class="btn" onclick="toggleFeedback(true)">${icon('feedback',16)} Give feedback</button>`)}${godBanner()}<div class="role-banner"><div class="role-avatar">${roleLabel().split(/\s+/).map(x=>x[0]).join('').slice(0,2)}</div><div class="role-copy"><b>${state.godMode?'God Mode with '+roleLabel()+' lens':roleLabel()+' experience'}</b><span>${state.godMode?'Full-system exploration is unlocked while the selected role remains a learning lens.':roleFocus()+'. Project navigation is filtered to the role while shared collaboration tools remain visible.'}</span></div><div class="role-tags"><span>${state.godMode?'Full ecosystem':'Role relevant'}</span><span>Project-aware</span><span>Audited</span></div></div><section class="project-hero"><div class="project-top"><div><h2>${project.name}</h2><p>${project.location} · ${project.client} · ${project.professional}</p></div><span class="status green">● In progress · ${project.progress}%</span></div><div class="stages">${stages.map((s,i)=>`<button class="stage ${s===project.stage?'active':''}" onclick="selectProjectStage('${s}')" title="Show ${s} stage tools"><i>${i+1}</i><span>${s}</span></button>`).join('')}</div><div class="stage-help"><b>${project.stage} stage:</b> ${V8_STAGE_COPY[project.stage]}</div></section><section class="datum-viewport"><div class="datum-world" style="min-width:${wide}px;transform:scale(${state.datumZoom})"><div class="datum-line"></div><div class="datum-origin"><img src="${LOGO}" alt="Architex bird"></div><div class="datum-label">DATUM<span>single line of truth</span></div><div class="datum-stage-badge"><b>${project.stage} · ${state.godMode?'God Mode':roleLabel()}</b>${ids.length} ${state.godMode?'stage-relevant':'role-relevant'} workspaces are active here.</div>${cards.map(c=>`<i class="datum-node" style="left:${c[1]}"></i>`).join('')}${cards.map(c=>v8DatumCard(...c)).join('')}</div><div class="datum-controls"><button onclick="stepDatumZoom(-.1)" title="Zoom out">−</button><input id="datumZoom" type="range" min=".65" max="1.35" step=".05" value="${state.datumZoom}" oninput="setDatumZoom(this.value)"><output id="datumOut">${Math.round(state.datumZoom*100)}%</output><button onclick="stepDatumZoom(.1)" title="Zoom in">+</button><button onclick="fitDatum()" title="Fit datum to view">${icon('expand',17)}</button></div></section>`;
  };

  function godToolRegistry(){const groups={};Object.entries(TOOLS).forEach(([id,t])=>(groups[t.group]??=[]).push([id,t]));return `<div class="god-tool-groups">${Object.entries(groups).map(([g,a])=>`<div class="god-tool-group"><h4>${g}</h4><div class="god-tool-grid">${a.map(([id,t])=>`<button class="god-tool" onclick="openTool('${id}','standalone')" title="Explore ${t.name}"><span class="nav-icon">${icon(t.icon,20)}</span><span><b>${t.name}</b><small>${t.status==='live'?'Live workspace':'Integration scaffold'}</small></span></button>`).join('')}</div></div>`).join('')}</div>`}
  function renderGodHome(){const roleList=Object.entries(V8_ROLE_LABELS);return `${pageHead('God Mode — Ecosystem Explorer','A demonstration and education layer for understanding Architex as one connected built-environment operating system.','god_mode','lavender',`<button class="btn ghost" onclick="openProjectSpace()">${icon('projects',16)} Open project datum</button><button class="btn" onclick="openTool('engineering_calc','standalone')">${icon('engineering_hub',16)} Engineering hub</button>`)}${godBanner()}<section class="god-hero"><h2>See the whole system. Learn where you fit.</h2><p>God Mode intentionally removes the normal UX filtering so any user can explore how clients, professionals, contractors, suppliers and project administrators collaborate across the same project spine. Use the role selector as a viewing lens, then open any workspace to understand inputs, outputs and handoffs.</p><div class="god-stats"><div class="god-stat"><b>${Object.keys(TOOLS).length}</b><span>Live and scaffolded tools</span></div><div class="god-stat"><b>8</b><span>Project workflow stages</span></div><div class="god-stat"><b>${Object.keys(V8_ROLE_LABELS).length}</b><span>User role lenses</span></div><div class="god-stat"><b>1</b><span>Datum / single line of truth</span></div></div></section><section class="god-section"><h3>Explore the project lifecycle</h3><p>Select a stage to open the project datum with every stage-relevant workspace visible.</p><div class="god-lifecycle">${Object.keys(V8_STAGE_MAP).map((s,i)=>`<button class="god-stage" onclick="godOpenStage('${s}')"><i>${i+1}</i><b>${s}</b></button>`).join('')}</div></section><section class="god-section"><h3>Understand the ecosystem of roles</h3><p>Change the selected role lens without losing God Mode access.</p><div class="god-role-grid">${roleList.map(([id,label])=>`<button class="god-role" onclick="godSetRole('${id}')"><i>${label.split(/\s+/).map(x=>x[0]).join('').slice(0,2)}</i><span><b>${label}</b><small>${V8_ROLE_FOCUS[id]||'Ecosystem participant'}</small></span></button>`).join('')}</div></section><section class="god-section"><h3>Typical information handoff</h3><p>The value is not isolated tools; it is traceable handoff between participants.</p><div class="god-handoff">${['Client brief','Architect / lead BEP','Engineers','QS / commercial','Contractor','Subcontractors','Suppliers','Authorities','Handover'].map((x,i,a)=>`<div class="node"><b>${x}</b></div>${i<a.length-1?'<div class="arrow">→</div>':''}`).join('')}</div></section><section class="god-section"><h3>Explore every workspace</h3><p>Open tools with demo/prototype context. Real production authority and protected project data remain permission-controlled.</p>${godToolRegistry()}</section>`}
  window.godOpenStage=function(s){project.stage=s;state.global='projects';state.mode='project';state.tool=null;renderAll();showToast(`${s} stage opened in God Mode.`)};
  window.godSetRole=function(r){if(typeof window.setRole==='function')window.setRole(r);else{state.role=r;renderAll()}setTimeout(()=>{if(state.godMode&&state.global!=='god'){state.global='god';state.tool=null;renderAll()}},0)};
  function godNavigator(){const nav=q('#navigator');nav.innerHTML=`<div class="nav-head"><div class="nav-compact-mark" title="God Mode Ecosystem Explorer">${icon('god_mode',27)}</div><div class="kicker">Demonstration & learning</div><div class="nav-title">God Mode</div><div class="nav-sub">Full ecosystem visibility · ${roleLabel()} lens</div></div><div class="nav-section"><div class="nav-heading">Explore</div><button class="nav-row active" style="${toneStyle('lavender')}" onclick="openGlobal('god')" title="Ecosystem Explorer"><span class="nav-icon">${icon('god_mode',21)}</span><span class="nav-label">Ecosystem Explorer</span></button><button class="nav-row" onclick="openProjectSpace()" title="Project datum"><span class="nav-icon">${icon('projects',21)}</span><span class="nav-label">Project datum</span></button><button class="nav-row" onclick="openStandalone()" title="All workspace tools"><span class="nav-icon">${icon('tools',21)}</span><span class="nav-label">All workspace tools</span></button><button class="nav-row" onclick="openTool('engineering_calc','standalone')" title="Engineer's Calculation Hub"><span class="nav-icon">${icon('engineering_hub',21)}</span><span class="nav-label">Engineering Hub</span></button><button class="nav-row" onclick="openTool('meetings','standalone')" title="Architex Meetings"><span class="nav-icon">${icon('meetings',21)}</span><span class="nav-label">Meetings</span></button><button class="nav-row" onclick="openTool('practice','standalone')" title="Practice & Project Management"><span class="nav-icon">${icon('practice_management',21)}</span><span class="nav-label">Practice & Project Management</span></button><button class="nav-row" onclick="openTool('wingman','standalone')" title="Wingman"><span class="nav-icon">${icon('wingman',21)}</span><span class="nav-label">Wingman</span></button></div><div class="nav-note"><b>Important:</b><br>God Mode is a demo/education experience. It should use safe demo data or read-only projections in production, never a client-side bypass of access control.</div>`}

  window.toggleGodMode=function(force){const on=typeof force==='boolean'?force:!state.godMode;state.godMode=on;if(on){state.global='god';state.mode='standalone';state.tool=null}else if(state.global==='god'){state.global='projects';state.mode='project';state.tool=null}renderAll();showToast(on?'God Mode enabled — full ecosystem exploration unlocked.':'God Mode off — returned to role-focused experience.')};
  function installGodToggle(){const top=q('.topbar');if(!top)return;let b=q('#godModeToggle');if(!b){b=document.createElement('button');b.id='godModeToggle';b.className='god-toggle';b.onclick=()=>toggleGodMode();const anchor=q('#wingmanTop');top.insertBefore(b,anchor)}b.classList.toggle('active',state.godMode);b.innerHTML=`${icon('god_mode',18)}<span>God Mode</span><small>${state.godMode?'On':'Explore'}</small>`;b.title=state.godMode?'Exit God Mode':'Explore the entire Architex ecosystem';document.body.classList.toggle('god-mode',state.godMode)}

  window.renderGlobalMenu=function(){const items=[...globalItems,...(state.godMode?[{id:'god',label:'God Mode Explorer',icon:'god_mode',tone:'lavender',meta:'ALL'}]:[])];q('#globalMenu').innerHTML=items.map(i=>`<button class="os-item ${state.global===i.id?'active':''}" style="${toneStyle(i.tone)}" onclick="openGlobal('${i.id}')" aria-label="${i.label}" title="${i.label}"><span class="icon-wrap">${icon(i.icon,25)}</span><span class="os-label">${i.label}</span><span class="os-meta">${i.meta}</span></button>`).join('')};
  window.openGlobal=function(id){if(id==='god'){if(!state.godMode)state.godMode=true;state.global='god';state.mode='standalone';state.tool=null;state.toolTab=0;renderAll();return}v8old.openGlobal(id)};

  function allToolGroups(mode){const groups={};Object.entries(TOOLS).forEach(([id,t])=>(groups[t.group]??=[]).push([id,t]));return Object.entries(groups).map(([g,a])=>`<div class="nav-section"><div class="nav-heading">${g}</div>${a.map(([id,t])=>`<button class="nav-row" style="${toneStyle(t.tone)}" onclick="openTool('${id}','${mode}')" title="${t.name}"><span class="nav-icon">${icon(t.icon,21)}</span><span class="nav-label">${t.name}</span>${t.status==='scaffold'?'<span class="badge">Scaffold</span>':''}</button>`).join('')}</div>`).join('')}
  window.toolGroups=function(mode){if(state.godMode&&mode==='project')return allToolGroups(mode);if(mode==='project'){const allowed=V8_ROLE_ACCESS[state.role]||V8_ROLE_ACCESS.architect,groups={};Object.entries(TOOLS).forEach(([id,t])=>{if(!allowed.includes(id)&&!['meetings','wingman','forms','project_passport'].includes(id))return;(groups[t.group]??=[]).push([id,t])});return Object.entries(groups).map(([g,a])=>`<div class="nav-section"><div class="nav-heading">${g}</div>${a.map(([id,t])=>`<button class="nav-row" style="${toneStyle(t.tone)}" onclick="openTool('${id}','project')" title="${t.name}"><span class="nav-icon">${icon(t.icon,21)}</span><span class="nav-label">${t.name}</span>${t.status==='scaffold'?'<span class="badge">Scaffold</span>':''}</button>`).join('')}</div>`).join('')}return v8old.toolGroups(mode)};

  window.renderNavigator=function(){if(state.tool==='engineering_calc'){engineeringNavigator();return}if(state.global==='god'&&!state.tool){godNavigator();return}v8old.renderNavigator()};
  window.setToolTab=function(i){if(state.tool==='engineering_calc'){setEngineeringTab(i);return}v8old.setToolTab(i)};
  window.renderMain=function(){if(state.tool==='engineering_calc'){q('#main').innerHTML=renderEngineering();setTimeout(()=>loadToolFrame('engineering_calc'),0);return}if(state.global==='god'&&!state.tool){q('#main').innerHTML=renderGodHome();return}v8old.renderMain();if(state.godMode){const main=q('#main');if(main&&!main.querySelector('.god-banner'))main.insertAdjacentHTML('afterbegin',godBanner())}};
  window.renderInspector=function(){if(state.tool!=='engineering_calc'){v8old.renderInspector();if(state.godMode){const b=q('#inspectBody');if(b&&!b.querySelector('.v8-god-inspect'))b.insertAdjacentHTML('afterbegin',`<div class="inspect-note v8-god-inspect"><b>God Mode active</b><br>Full-system visibility is for exploration. Authority, professional responsibility and protected records remain governed.</div>`)}return}q('#inspectTitle').textContent="Engineer's Calculation Hub";q('#inspectSub').textContent=state.mode==='project'?project.name:'Standalone engineering';const tab=TOOLS.engineering_calc.tabs[state.toolTab]||TOOLS.engineering_calc.tabs[0];q('#inspectBody').innerHTML=`<div class="inspect-note"><b>${tab.group} · ${tab.label}</b><br>The original calculation workspace is active inside Datum OS. Results remain advisory working evidence until reviewed by the responsible professional.</div><div class="inspect-block"><h4>Project integration</h4><p>${state.mode==='project'?`${project.name}<br>${project.stage} stage · Rev ${project.revision}<br>Save calculations against a project record and link them to drawings, RFIs, meetings or inspections.`:'No project is assumed. Save an unassigned working calculation or attach a project later.'}</p></div><div class="inspect-block"><h4>Controlled outputs</h4><p>Calculation record<br>Derivation / result snapshot<br>Referenced standard and inputs<br>Author / reviewer / revision<br>Linked drawing or project record<br>Audit event</p></div><div class="inspect-block"><h4>Professional boundary</h4><p>A calculator result does not issue a drawing, certify compliance or replace engineering judgement. Professional review and the destination workflow remain mandatory.</p></div>${state.engineeringSaved?'<div class="inspect-note"><b>Saved in this demo</b><br>A controlled calculation record has been represented in the project workflow.</div>':''}`};
  window.renderTopbar=function(){v8old.renderTopbar();installGodToggle();if(state.godMode){const s=q('#scopePill');if(s)s.textContent='God Mode · demo explorer'}if(state.tool==='engineering_calc'){const p=q('#projectChip');if(p)p.textContent=state.mode==='project'?'● '+project.name+' · Engineering':'○ Engineering · unassigned'}};
  const priorRenderAll=window.renderAll;window.renderAll=function(){priorRenderAll();installGodToggle();document.body.classList.toggle('god-mode',state.godMode)};

  // Make the Engineering Hub obvious to generic engineers in the existing role experience.
  renderAll();
})();
</script>

<script src="/assets/js/api-client.js"></script><script src="/assets/js/project-datum.js"></script><script src="/assets/js/tool-registry.js"></script><script src="/assets/js/shell.js"></script><script src="/assets/js/demo-sandbox.js"></script>
</body>
</html>
